// JFLT Listening Complete — Balanced answer distribution
// Distribution: L1=15 / L2=35 / L3=25 / L4=15 (Total: 90 questions)

export const LISTENING = {
  1: [
    { topic: "Patrol orders — route and timing", passage: "All call signs, this is Zero. Routine patrol along Route Blue will depart at fourteen forty-five. Estimated return time is seventeen hundred. All vehicles must be fuelled and ready by fourteen fifteen. Any questions, contact the duty officer. Zero, out.", question: "By what time must vehicles be ready?", options: ["14:15 — readiness time", "14:45 — departure time", "17:00 — return time", "14:00 — one hour early"], answer: 0, ex: "Vehicles must be ready by 14:15 — 30 minutes before the 14:45 departure. Never confuse readiness time with departure time." },
    { topic: "Tannoy — Quick Reaction Force", passage: "Attention, attention. All personnel assigned to the Quick Reaction Force are to report to the vehicle park at oh-six-hundred tomorrow morning. Bring your personal weapon, full combat kit, and two days rations. Attendance is mandatory. Acknowledge receipt to Sergeant Kim at extension two-four-seven.", question: "Where should Quick Reaction Force personnel report?", options: ["The operations room", "The vehicle park", "Sergeant Kim's office", "The armoury"], answer: 1, ex: "QRF personnel must report to the vehicle park. Extension 247 is for confirmation only — a common distractor at Level 1." },
    { topic: "Casualty report — medevac request", passage: "Sunray, this is Bravo Two. We have one casualty, non-life-threatening, suspected broken ankle. Casualty is male, approximately twenty-five years old. We are at grid four-four-seven Echo. Request medical evacuation. Over.", question: "What is the nature of the casualty's injury?", options: ["Life-threatening head wound", "Broken leg", "Suspected broken ankle", "Chest injury"], answer: 2, ex: "The injury is a suspected broken ankle. 'Suspected' means not yet confirmed. The injury is also non-life-threatening — a key detail at Level 1." },
    { topic: "Supply confirmation", passage: "Hello, this is the supply sergeant from Alpha Company. We need to request forty litres of diesel, ten cases of water, and spare batteries for the radios. Can this be delivered by sixteen hundred today? Confirmed. Delivery will be at fifteen thirty.", question: "When will the supplies be delivered?", options: ["16:00 — as requested", "15:00 — one hour early", "End of day", "15:30 — confirmed delivery"], answer: 3, ex: "Delivery confirmed at 15:30, although the request was for 16:00. Tests whether you heard the confirmed time vs the requested time — a typical Level 1 attention task." },
    { topic: "Visibility report", passage: "Met office report. Visibility this morning is reduced to two hundred metres due to dense fog. Conditions are expected to improve after ten hundred when wind from the south picks up. All flight operations are suspended until visibility exceeds one thousand metres. Ground vehicle movement requires escort vehicles. Met office, out.", question: "What is causing the reduced visibility?", options: ["Dense fog", "Heavy rain", "Smoke from fires", "A sandstorm"], answer: 0, ex: "Reduced visibility is due to dense fog. The other distractors are typical visibility-reducing conditions but were not mentioned in the briefing — Level 1 tests whether you can isolate the actual cause stated." },
    { topic: "Daily briefing", passage: "Good morning, team. Today's schedule is as follows. Physical training begins at zero five thirty. Breakfast at zero seven hundred. Briefing at zero eight hundred. Field exercise from zero nine hundred to twelve hundred. Lunch at twelve thirty. Equipment maintenance in the afternoon. Any questions?", question: "What activity follows the morning briefing?", options: ["Physical training", "Field exercise", "Breakfast", "Lunch"], answer: 1, ex: "Field exercise follows the briefing, running from 09:00 to 12:00. Sequence comprehension at Level 1." },
    { topic: "Change of command notice", passage: "Attention all personnel. Major Adams will assume command of Bravo Company on Wednesday at oh-nine-hundred. The handover ceremony will take place at the parade square. The outgoing commander, Major Patel, will deliver a brief farewell address. All officers and senior non-commissioned officers are required to attend. Working dress is the order. Out.", question: "Who is taking command of Bravo Company?", options: ["Major Patel", "Captain Smith", "Major Adams", "Lieutenant Brown"], answer: 2, ex: "Major Adams is taking command. Major Patel is the outgoing commander — a typical L1 distractor that tests whether you tracked direction (incoming vs outgoing) carefully." },
    { topic: "Radio check procedure", passage: "All stations, this is Hotel Six. Radio check, over. Hotel One, loud and clear, over. Hotel Two, loud and clear, over. Hotel Three, you are weak but readable, please change to alternate frequency. Hotel Six, all stations roger. Out.", question: "Which station was asked to change frequency?", options: ["Hotel One", "Hotel Two", "Hotel Six", "Hotel Three"], answer: 3, ex: "Hotel Three was weak but readable, so was asked to change to alternate frequency. Note: this is a key NATO radio procedure detail at Level 1." },
    { topic: "Vehicle workshop hours", passage: "Attention all drivers. The vehicle workshop is open from oh-eight-hundred to seventeen hundred Monday through Friday. Saturday hours are oh-eight-hundred to twelve hundred. The workshop is closed on Sundays. Emergency repairs may be requested by contacting the duty mechanic on extension three-five-two. End of message.", question: "What time does the workshop close on Saturdays?", options: ["12:00", "08:00", "17:00", "It does not open on Saturdays"], answer: 0, ex: "Saturday hours end at twelve hundred (12:00). Don't confuse with weekday closing time (17:00) — Level 1 tests precise time boundaries against day-specific information." },
    { topic: "Range safety briefing", passage: "Listen up. Live firing on Range Three begins at thirteen hundred today. The danger area extends two kilometers downrange. All personnel must remain behind the safety line. Red flags will be flying when firing is in progress. The cease-fire signal is three long whistle blasts. Range warden is Sergeant O'Brien. Any questions, see him before firing starts.", question: "What signal indicates cease-fire?", options: ["A red flag", "Three long whistle blasts", "A radio call", "A loudspeaker announcement"], answer: 1, ex: "Cease-fire is signalled by three long whistle blasts. The red flag indicates firing IS in progress (not cease-fire) — a typical Level 1 trap that tests whether you matched the signal to the correct event." },
    { topic: "Airport boarding announcement", passage: "Attention passengers. Final boarding call for Military Air Transport flight three-five-seven to Frankfurt. Please proceed to Gate Twelve immediately. The aircraft will depart in fifteen minutes. Passengers should have their boarding passes and identification ready for inspection. This is the final call.", question: "Which gate should passengers go to?", options: ["Gate 5", "Gate 7", "Gate 12", "Gate 15"], answer: 2, ex: "搭乗口は Gate Twelve (12)。Flight number 357 や 'fifteen minutes' は distractor。L1 の数字聴き取り問題で、複数の数字情報の中から該当するものを正確に抽出する。" },
    { topic: "Phone message — pickup change", passage: "Hello, this is Sergeant Rivera leaving a message for Captain Lee. Your pickup tomorrow morning has been changed from oh-seven-hundred to oh-six-thirty. The transport will meet you at the front gate. Please confirm receipt of this message by calling extension four-two-one. Thank you.", question: "What time is the new pickup?", options: ["06:00", "07:00", "07:30", "06:30"], answer: 3, ex: "新しい時刻は oh-six-thirty (06:30)。元の時刻 07:00 は変更前の distractor。L1 の電話メッセージ — 'changed from X to Y' のパターンで、変更後の値を聴き取る訓練。" },
    { topic: "Shuttle bus announcement", passage: "Attention all personnel. The shuttle bus to the airbase departs from Bus Stop Three every thirty minutes between oh-five-hundred and twenty-three hundred. Outside these hours, transport must be requested from the duty driver on extension nine-one-one. The journey takes approximately twenty minutes. End of announcement.", question: "How often does the shuttle bus depart?", options: ["Every 30 minutes", "Every 15 minutes", "Every hour", "Every 2 hours"], answer: 0, ex: "シャトルバスは every thirty minutes (30分毎)。所要時間 'twenty minutes' や Bus Stop Three は distractor。L1 の頻度聴き取り問題で、間隔と所要時間を区別する力が問われる。" },
    { topic: "Direction enquiry on base", passage: "Excuse me, can you tell me where the medical centre is? Yes, of course. Walk straight ahead past the parade square, then turn left at the second building. The medical centre is the white building with the red cross sign. It takes about five minutes on foot. Thank you very much.", question: "Where do you turn left?", options: ["At the parade square", "At the second building", "At the first building", "At the red cross sign"], answer: 1, ex: "'turn left at the second building' から正解は二棟目。parade square は通り過ぎる場所、red cross sign は最終目印 — distractor として混同しやすい。L1 の道案内 — 順序立てた指示の聴き取り問題。" },
    { topic: "Train delay announcement", passage: "Attention passengers. The eleven hundred train to Rome has been delayed by approximately twenty minutes due to a technical problem. The new departure time is eleven-twenty. The train will depart from Platform Four as originally scheduled. We apologise for the inconvenience. Thank you for your patience.", question: "What is the reason for the delay?", options: ["Bad weather", "An accident on the line", "A technical problem", "Heavy passenger traffic"], answer: 2, ex: "遅延理由は a technical problem。Platform Four や twenty minutes (遅延時間) は distractor。L1 の理由聴き取り問題で、複数の情報の中から原因に該当する部分のみを抽出する。" }
  ],
  2: [
    { topic: "Intelligence briefing — bridge surveillance", passage: "Good morning. I am the intelligence officer for Task Force Kestrel. The current threat level in our area of operations is assessed as moderate. Overnight reconnaissance reported a vehicle with unknown markings travelling south along Route Orange at approximately oh-three-hundred. The vehicle stopped near the bridge at grid five-five-two Foxtrot for approximately twenty minutes before continuing south. We assess this as likely reconnaissance activity. All patrols are advised to approach the bridge area with caution and report any unusual activity immediately.", question: "Why does the intelligence officer advise caution near the bridge?", options: ["The bridge has been structurally damaged", "The area may have been subject to hostile reconnaissance", "Enemy forces have been confirmed in the area", "An improvised explosive device was found nearby"], answer: 1, ex: "The vehicle stopped near the bridge, assessed as likely reconnaissance activity. Caution follows from suspected hostile interest — not a confirmed enemy presence." },
    { topic: "Checkpoint orders — documentation", passage: "Listen carefully. The mission is to establish a vehicle checkpoint on Route Amber at grid three-three-zero Delta. The checkpoint will be operational from zero seven hundred to nineteen hundred. All vehicles will be stopped and occupants identification checked. Vehicles carrying military equipment require special authorisation documents. Any vehicle lacking correct documentation will be held pending further instructions from headquarters. At no time are weapons to be pointed at civilian vehicles during routine checks.", question: "What happens to vehicles without correct documentation?", options: ["They are immediately turned back", "They are escorted to headquarters", "They are held pending further instructions from headquarters", "Their occupants are arrested"], answer: 2, ex: "Vehicles lacking correct documentation are held pending further instructions. 'Pending' = while waiting for. Standard Level 2 procedure comprehension." },
    { topic: "Aerial reconnaissance — sortie debrief", passage: "The reconnaissance sortie departed at oh-six-fifteen and covered the designated area in the northern sector. Imagery was collected at three waypoints as planned. At waypoint Bravo, the crew observed a concentration of approximately thirty vehicles in a treeline approximately two kilometres east of the road. The vehicles appeared to be military trucks. The sortie recovered at oh-nine-ten without incident. Full imagery analysis will be completed within four hours.", question: "What did the crew observe at waypoint Bravo?", options: ["An empty treeline east of the road", "A bridge under construction", "A civilian convoy heading north", "Approximately thirty military trucks in a treeline"], answer: 3, ex: "At waypoint Bravo, the crew observed approximately thirty vehicles, two kilometres east of the road, appearing to be military trucks. Full detail retrieval combining location, number, and nature." },
    { topic: "Civil-military liaison meeting", passage: "Thank you for coming today, Mister Mayor. I want to assure you that our troops are here to support the local community, not to interfere in civilian life. We have established a liaison office at the town hall where residents can raise concerns directly with my staff. Our engineers will begin work on repairing the water supply on Monday. We expect the repairs to take approximately three days.", question: "How long will the water supply repairs take?", options: ["Three days", "One day", "Two days", "One week"], answer: 0, ex: "Repairs will take approximately three days. 'Approximately' = roughly, about. Level 2 listening tests comprehension of spoken estimates." },
    { topic: "Operational orders — patrol mission", passage: "The mission is to conduct a vehicle patrol along Route Yellow. Patrol composition will be three vehicles. Departure time is zero eight hundred. Estimated patrol duration is six hours. Maintain radio contact with headquarters every thirty minutes. Report any unusual activity immediately. Rules of engagement remain unchanged. Return to base by fourteen hundred.", question: "How often must the patrol report to headquarters?", options: ["Every fifteen minutes", "Every thirty minutes", "Every hour", "Only when contact is made"], answer: 1, ex: "Radio contact every 30 minutes. Communication intervals are commonly tested at Level 2." },
    { topic: "Security briefing", passage: "Following recent incidents, security procedures have been updated. All personnel entering the base must show their identification card. Vehicles will undergo inspection by the gate guards. Bags must be opened for inspection. These procedures apply to all personnel without exception, including senior officers. Compliance is mandatory.", question: "Who do the new security procedures apply to?", options: ["Only junior personnel", "Only visitors", "All personnel including senior officers", "Only personnel from outside the unit"], answer: 2, ex: "Procedures apply to all personnel without exception, including senior officers. Tests understanding of universal application of rules." },
    { topic: "Weather impact briefing", passage: "Severe weather is expected over the next twenty-four hours. Heavy snow and strong winds will affect operations across the entire area. All non-essential outdoor activities are postponed. Vehicle movement is restricted to essential operations only. Patrols will use the alternative northern route which remains accessible. Monitor weather updates every two hours.", question: "What is the situation regarding patrols?", options: ["All patrols are cancelled", "Patrols continue on the original route", "Only foot patrols are permitted", "Patrols will use the alternative northern route"], answer: 3, ex: "Patrols will use the alternative northern route, which remains accessible. Conditional adaptation is a key Level 2 listening skill." },
    { topic: "Medical evacuation procedure", passage: "Listen up. Medical evacuation procedures have been updated. For all casualties, first call the medical centre at extension two-zero-six. Provide casualty number, type of injury, and grid location. The medical team will despatch an ambulance within five minutes. Helicopter evacuation is available for serious cases requiring movement to the regional hospital.", question: "When is helicopter evacuation available?", options: ["For serious cases requiring movement to the regional hospital", "For all casualties", "Only at night", "Only during weekday operations"], answer: 0, ex: "Helicopter evacuation is available for serious cases requiring transfer to the regional hospital. Conditions for specialised resources are tested at Level 2." },
    { topic: "Joint exercise briefing", passage: "Welcome to the multinational exercise briefing. This exercise involves forces from four nations. The training objective is to improve interoperability between participating units. The exercise lasts ten days. Live-fire training will be conducted only at designated ranges and only with proper safety supervision. Cultural awareness briefings are scheduled for tomorrow morning.", question: "What is the main objective of the exercise?", options: ["To test new equipment", "To improve interoperability between units", "To train new recruits", "To evaluate individual performance"], answer: 1, ex: "The training objective is to improve interoperability. 'Interoperability' is a core NATO concept tested across all levels." },
    { topic: "Patrol incident report", passage: "Headquarters, this is Patrol Three reporting an incident. At approximately fourteen-thirty, while patrolling Route Green near the village, we encountered a civilian crowd blocking the road. The crowd was protesting peacefully against recent fuel price increases. We did not engage. We took the alternative route via the bridge and continued the mission. No casualties or damage. Patrol Three, out.", question: "How did the patrol respond to the crowd?", options: ["They dispersed the crowd", "They called for reinforcements", "They did not engage and took an alternative route", "They returned to base immediately"], answer: 2, ex: "The patrol did not engage and took the alternative route. Conflict avoidance and route adaptation — common Level 2 scenario." },
    { topic: "Equipment status report", passage: "Quartermaster, this is Charlie Company reporting equipment status. Currently we have eighty percent of authorised equipment serviceable. The remaining twenty percent requires maintenance. Two vehicles are awaiting parts that should arrive Friday. Three radios have been sent for repair. Replacement equipment is expected within seven working days.", question: "What proportion of equipment requires maintenance?", options: ["Ten percent", "Thirty percent", "Forty percent", "Twenty percent"], answer: 3, ex: "Twenty percent requires maintenance. Specific percentages are common Level 2 listening targets." },
    { topic: "Logistical request", passage: "Headquarters, this is Bravo Company. Resupply request as follows. We require five hundred litres of fuel, two thousand rations, and ammunition for the planned exercise next week. Delivery should reach us by Wednesday. Our location is grid two-two-five Tango. Acknowledge receipt of this request, please.", question: "By when does Bravo Company need the supplies?", options: ["Wednesday", "Today", "Tomorrow", "End of next week"], answer: 0, ex: "Supplies needed by Wednesday for the planned exercise next week. Delivery deadlines are key Level 2 details." },
    { topic: "Reconnaissance debrief", passage: "Reconnaissance team reporting. We patrolled the eastern sector for six hours. Visibility was good throughout. We observed routine civilian activity in the village of Saint Mary. No military vehicles or personnel were seen. The bridge at grid one-one-eight is intact and passable. We recommend continued routine surveillance of the area. End of report.", question: "What does the reconnaissance team recommend?", options: ["Immediate withdrawal from the area", "Continued routine surveillance", "Increased military presence", "Civilian evacuation"], answer: 1, ex: "The team recommends continued routine surveillance. Recommendations following reconnaissance are commonly tested at Level 2." },
    { topic: "Search operation briefing", passage: "Today's mission is a search operation in the wooded area north of the river. We are looking for a missing civilian, last seen yesterday afternoon. The search area is divided into four sectors. Each platoon will search one sector. Maintain visual contact with neighbouring soldiers. Report any findings immediately. The search will continue until eighteen hundred or until the missing person is located.", question: "When will the search end?", options: ["At twelve hundred", "At fifteen hundred", "At eighteen hundred or when the person is found", "When weather conditions deteriorate"], answer: 2, ex: "The search ends at 18:00 or when the missing person is located, whichever comes first. Conditional time limits — Level 2 listening." },
    { topic: "Damage assessment", passage: "Following last night's storm, damage assessment is as follows. Three vehicles sustained minor damage from falling debris. The repair workshop has been flooded. Communications equipment is fully operational. The main building is undamaged. Estimated repair time is forty-eight hours. Reduced operational tempo is recommended during this period.", question: "What is the estimated repair time?", options: ["Twelve hours", "Twenty-four hours", "One week", "Forty-eight hours"], answer: 3, ex: "Estimated repair time is 48 hours. Specific durations following incidents are common Level 2 details." },
    { topic: "Patrol tasking — route and objectives", passage: "Good morning. This is the patrol order for today's mission. Call sign Eagle Two will conduct a route reconnaissance along Highway Seven from grid three-three-five Delta to grid four-four-two Echo. Departure time is oh-nine-hundred. Estimated duration is five hours. Your primary task is to assess road conditions and identify any obstacles that could impede convoy movement. Report any civilian activity near the route. Maintain radio contact with headquarters every thirty minutes. If you encounter any security concerns, halt the patrol and request guidance before proceeding. Questions?", question: "What should the patrol do if they observe a potential security problem?", options: ["Stop the patrol and seek instructions before continuing.", "Continue the patrol and include the observation in the final report.", "Report the concern immediately while continuing to move forward.", "Return to base and file a detailed incident report."], answer: 0, ex: "'If you encounter any security concerns, halt the patrol and request guidance before proceeding' — option A paraphrases 'halt' as 'stop' and 'request guidance before proceeding' as 'seek instructions before continuing'. B and C contradict the halt instruction. D adds an action (return to base) not mentioned. Distractor C is tempting because it mentions reporting, which is generally good practice, but the explicit instruction is to halt first." },
    { topic: "Quick reaction force alert", passage: "Attention all Quick Reaction Force personnel. This is an alert notification. A patrol has reported contact with an unknown armed group at grid two-two-eight Charlie. The patrol is currently taking cover and has requested immediate support. Quick Reaction Force is to deploy within fifteen minutes. Load personal weapons, body armor, and sufficient ammunition for sustained engagement. Assemble at the vehicle park. The operations officer will provide additional briefing during movement. This is not a drill. I repeat, this is not a drill.", question: "How quickly must the Quick Reaction Force be ready to deploy?", options: ["Immediately upon hearing the alert notification.", "Within a quarter of an hour from the time of this message.", "As soon as the operations officer completes the additional briefing.", "After loading weapons and assembling at the vehicle park."], answer: 1, ex: "'Deploy within fifteen minutes' — option B paraphrases '15 minutes' as 'quarter of an hour'. A is wrong (the timeframe is explicit: 15 minutes, not 'immediately'). C misreads (briefing happens during movement, not before deployment). D lists preparatory actions but doesn't capture the time requirement. The question tests whether listeners caught the specific timeframe amid urgent tone." },
    { topic: "Security posture change", passage: "All stations, this is headquarters. Effective immediately, security posture is elevated to Bravo. All personnel are to carry personal weapons at all times. Increased vigilance is required at entry points. Vehicle searches will be conducted on one hundred percent of vehicles entering the compound. Off-base movement is restricted to mission-essential tasks only. Personnel planning to leave the base must obtain prior approval from their unit commander. This posture will remain in effect until further notice.", question: "What restriction does the new security posture place on personnel movement?", options: ["All personnel must remain on base without exception.", "Movement between different areas of the base is prohibited.", "Leaving the base requires unit commander approval and must be for essential duties.", "Vehicle use is limited to security patrols and emergency response."], answer: 2, ex: "'Off-base movement is restricted to mission-essential tasks only' and 'must obtain prior approval from their unit commander' — option C captures both conditions. A overstates (mission-essential movement is permitted). B misreads (the restriction is off-base, not on-base movement). D introduces vehicle restrictions not mentioned. Level 2 listening tests whether listeners can combine two related pieces of information." },
    { topic: "Training exercise schedule change", passage: "Attention all personnel participating in Exercise Northern Shield. Due to adverse weather conditions, the live-fire portion of the exercise has been postponed by twenty-four hours. The revised schedule is as follows. Day one: classroom instruction and equipment preparation. Day two: movement to the training area and defensive position construction. Day three: live fire, which was originally scheduled for day two. All other aspects of the exercise remain unchanged. Ensure your unit is aware of this modification.", question: "Why has the exercise schedule been modified?", options: ["To allow additional time for classroom instruction.", "To coordinate with the availability of the training area.", "Because equipment preparation is taking longer than anticipated.", "Because weather conditions make the original timing unsuitable."], answer: 3, ex: "'Due to adverse weather conditions, the live-fire portion has been postponed' — option D paraphrases 'adverse weather conditions' as 'weather conditions make the original timing unsuitable'. A, B, C are plausible operational reasons but not stated. Distractor A uses 'classroom instruction' from the passage to tempt surface listeners. The question tests causal listening: identifying why something happened." },
    { topic: "Intelligence summary — pattern analysis", passage: "Good morning. This is the intelligence update for the twenty-fourth of November. Over the past seventy-two hours, we have observed an increase in reconnaissance activity in the northern sector. Three separate incidents of individuals photographing checkpoints have been reported. Additionally, there has been a noticeable reduction in civilian traffic along Route Orange, which typically sees heavy use. These patterns may indicate preparation for hostile action. All patrols are advised to maintain heightened awareness. Report any suspicious activity immediately through normal channels.", question: "What does the intelligence officer suggest the observed patterns might indicate?", options: ["That reconnaissance is being conducted in preparation for a possible attack.", "That civilian populations are avoiding military checkpoints.", "That Route Orange will be closed to civilian traffic in the near future.", "That additional checkpoints should be established in the northern sector."], answer: 0, ex: "'These patterns may indicate preparation for hostile action' — option A paraphrases 'preparation for hostile action' as 'preparation for a possible attack'. A describes one pattern but misses the interpretation. C and D are actions that might follow, but aren't what the patterns indicate. The test: understanding tentative analytical conclusions ('may indicate') vs. definitive facts." },
    { topic: "Threat assessment briefing", passage: "The current threat level in our area of operations remains moderate. The primary threat continues to be improvised explosive devices emplaced along main supply routes. Secondary threats include small arms fire directed at patrols and indirect fire attacks on bases. The most vulnerable time for patrols is during morning hours between oh-six-hundred and oh-nine-hundred, when visibility is improving but still limited. Explosive ordnance disposal teams are on standby to respond to suspected device discoveries. All personnel are reminded to report anything unusual along roadways.", question: "According to the briefing, when are patrols most at risk?", options: ["During hours of complete darkness when visibility is minimal.", "In the early morning when light conditions are transitional.", "Throughout the day whenever they are traveling on main supply routes.", "When explosive ordnance disposal teams are unavailable to respond."], answer: 1, ex: "'Most vulnerable time for patrols is during morning hours between oh-six-hundred and oh-nine-hundred, when visibility is improving but still limited' — option B paraphrases this as 'early morning when light conditions are transitional'. A is wrong (the threat is during improving visibility, not darkness). C overgeneralizes. D misreads (EOD teams are on standby; their absence isn't mentioned as the vulnerability factor). The skill: understanding qualified temporal claims." },
    { topic: "Civil unrest warning", passage: "Be advised that a large public demonstration is planned for tomorrow afternoon in the city center. Local authorities estimate approximately five thousand participants. The demonstration is expected to remain peaceful, however there is potential for the situation to escalate. Military personnel are instructed to avoid the city center area between fourteen hundred and eighteen hundred unless mission requirements specifically necessitate presence there. If you must operate in that area, travel in vehicles and maintain communication with your operations center.", question: "What guidance is given to military personnel regarding the demonstration?", options: ["They must coordinate their movements with local authorities.", "They are prohibited from entering the city center until further notice.", "They should stay clear of the area unless operationally necessary.", "They must travel on foot rather than in vehicles to avoid drawing attention."], answer: 2, ex: "'Military personnel are instructed to avoid the city center area... unless mission requirements specifically necessitate presence there' — option C paraphrases 'avoid... unless necessitate' as 'stay clear... unless operationally necessary'. A is not stated. B is too absolute (the guidance allows mission-necessary presence). D inverts the guidance (if they must go, travel IN vehicles). The question tests conditional instructions: avoid unless X." },
    { topic: "Supply convoy notification", passage: "This is a logistics notification for all units. The weekly supply convoy will depart the main supply depot at oh-seven-hundred on Wednesday and is scheduled to arrive at forward operating bases between twelve hundred and sixteen hundred the same day. Units requiring supplies must have their requests submitted to the logistics office no later than eighteen hundred on Monday. Emergency requests can be accommodated but require battalion commander approval. The convoy will follow Route Blue and estimated travel time is four to six hours depending on conditions.", question: "By when must routine supply requests be submitted?", options: ["By seven o'clock in the morning on Wednesday when the convoy departs.", "Between noon and four o'clock on Wednesday when supplies arrive.", "No later than eighteen hours before the convoy is scheduled to depart.", "By six o'clock in the evening on Monday."], answer: 3, ex: "'Requests submitted to the logistics office no later than eighteen hundred on Monday' — option D converts 18:00 to 'six o'clock in the evening'. A, B use convoy timing but aren't the deadline for submissions. D misparses 'eighteen hundred' as '18 hours'. Common Level 2 listening trap: discriminating between multiple time references in one passage." },
    { topic: "Equipment maintenance schedule", passage: "Attention all platoon sergeants. Scheduled maintenance for unit vehicles will be conducted next week according to the following schedule. First Platoon on Monday. Second Platoon on Tuesday. Third Platoon on Wednesday. Each platoon must bring their vehicles to the motor pool by oh-eight-hundred on their assigned day. Maintenance is expected to take six to eight hours. Platoons will operate with reduced mobility on their maintenance day. Plan your operational taskings accordingly.", question: "What impact will the maintenance schedule have on platoon operations?", options: ["Each platoon will have decreased transport capacity on one specific day.", "Platoons will be unable to conduct any operations during the entire week.", "All platoons must coordinate to share vehicles during maintenance periods.", "Operations requiring vehicles must be postponed until the following week."], answer: 0, ex: "'Platoons will operate with reduced mobility on their maintenance day' — option A paraphrases 'reduced mobility' as 'decreased transport capacity' and 'on their maintenance day' as 'on one specific day'. A overstates (only one day per platoon, and 'reduced' not 'unable'). C and D add coordination requirements not mentioned. The inference: understanding 'reduced mobility' means limited but not zero capability." },
    { topic: "Fuel consumption advisory", passage: "All unit leaders, this is the logistics officer. Fuel consumption over the past two weeks has exceeded projected levels by approximately twenty percent. If this trend continues, we may face supply shortages before the next major resupply. Effective immediately, non-essential vehicle movements should be minimized. Combine tasks where possible to reduce unnecessary trips. Generator usage should be limited to mission-essential power requirements. These conservation measures will remain in place until consumption returns to planned levels.", question: "What prompted the issuance of conservation measures?", options: ["A delay in the arrival of the next major fuel resupply shipment.", "Current fuel usage patterns exceeding anticipated consumption rates.", "Requirements to reduce the environmental impact of operations.", "Directives from higher headquarters to cut operational costs."], answer: 1, ex: "'Fuel consumption... has exceeded projected levels' and 'If this trend continues, we may face supply shortages' — option B captures the cause as 'current usage patterns exceeding anticipated consumption rates'. A is wrong (no delay is mentioned; the concern is the consumption rate). C and D are plausible policy drivers but not stated. The skill: distinguishing the immediate cause from potential consequences or unstated broader reasons." },
    { topic: "Medical evacuation request — procedure", passage: "All commanders, this is a reminder of medical evacuation request procedures. When requesting evacuation for casualties, provide the following information. First, your call sign and location as a grid reference. Second, number of casualties and their priority categories. Third, security situation at the evacuation site. Fourth, method of marking the landing zone. Medical evacuation helicopters can typically arrive within thirty to forty-five minutes of request during daylight hours. Night evacuations may take longer depending on availability and weather. Ensure casualties are prepared for movement before the aircraft arrives.", question: "What must commanders include when requesting medical evacuation?", options: ["The names and ranks of all casualties requiring evacuation.", "Confirmation that casualties have been prepared for movement.", "Details of the security environment where the helicopter will land.", "The estimated time needed for evacuation based on casualty priority."], answer: 2, ex: "The briefing lists four required items, including 'security situation at the evacuation site' — option C paraphrases this as 'security environment where the helicopter will land'. A is not in the list (call sign, not individual names). B is required but AFTER the request (preparation happens before aircraft arrival). D inverts the relationship (commanders don't estimate time; they're told typical times). The question tests recall of procedural steps." },
    { topic: "Public health advisory", passage: "This is a health advisory for all personnel. Medical staff have identified an increase in heat-related illnesses over the past week. Temperatures are forecast to remain above thirty-five degrees Celsius for the next ten days. All outdoor activities should be scheduled for early morning or late evening when possible. Personnel working outside during peak heat hours must take breaks in shaded or air-conditioned areas every hour. Ensure water consumption is increased. Leaders are responsible for monitoring their personnel for signs of heat stress. Report any cases of heat illness to the medical center immediately.", question: "What action are leaders specifically directed to take?", options: ["Reschedule all outdoor activities to morning or evening periods.", "Ensure their personnel take hourly breaks in cooled locations.", "Increase the water rations distributed to personnel under their command.", "Observe their subordinates for indications of heat-related problems."], answer: 3, ex: "'Leaders are responsible for monitoring their personnel for signs of heat stress' — option D paraphrases 'monitoring their personnel' as 'observe their subordinates' and 'signs of heat stress' as 'indications of heat-related problems'. A and B are recommendations ('should'), not directed responsibilities for leaders specifically. C adds a distribution responsibility not stated. The skill: distinguishing general guidance from specific assigned responsibilities." },
    { topic: "Use of force briefing", passage: "Rules of engagement briefing for today's patrol. You may use force in self-defense or in defense of others who are under attack. Before using force, you must issue a verbal warning if the tactical situation permits. If warning is not possible due to immediate threat, you may engage without warning. All use of force must be proportional to the threat faced. Deadly force is authorized only when lesser means have failed or are unavailable and serious harm is imminent. Document all incidents involving use of force immediately after the situation is controlled. Legal review will be conducted for all such incidents.", question: "Under what condition may force be used without giving a warning first?", options: ["When the immediacy of the threat prevents the opportunity to warn.", "Whenever the patrol leader determines a warning is tactically inappropriate.", "After lesser means of force have been attempted unsuccessfully.", "When legal review has been conducted and deadly force is authorized."], answer: 0, ex: "'If warning is not possible due to immediate threat, you may engage without warning' — option A paraphrases 'not possible due to immediate threat' as 'immediacy of the threat prevents the opportunity to warn'. B is too subjective (the criterion is threat immediacy, not leader judgment about tactical appropriateness). C describes conditions for deadly force, not for waiving warnings. D reverses sequence (legal review happens after incidents). Level 2 listening: identifying specific conditions within procedural guidance." },
    { topic: "Detention procedures briefing", passage: "Procedures for handling detained persons are as follows. Detainees must be searched immediately for weapons and contraband. They must then be moved to a secure holding area. Detainees are to be provided with water and allowed to sit in the shade. They may not be questioned except by personnel specifically trained and authorized for interrogation. All detentions must be documented including name if known, time and location of detention, and reason for detention. This information must be forwarded to the operations center within two hours. Detainees will be transferred to military police custody as soon as transport is available.", question: "Who is permitted to conduct questioning of detained individuals?", options: ["The patrol leader who made the decision to detain the individual.", "Only those with specific training and authorization for interrogation.", "Any personnel who have completed basic military training.", "Personnel designated by the operations center on a case-by-case basis."], answer: 1, ex: "'They may not be questioned except by personnel specifically trained and authorized for interrogation' — option B directly rephrases this. A, C, D all loosen the restriction in various ways. The question tests understanding of categorical restrictions ('may not... except by')." },
    { topic: "Radio silence directive", passage: "All stations, this is headquarters. Radio silence is now in effect for the next six hours. Transmit only in case of emergency or enemy contact. Emergency transmissions should be kept to minimum essential information. Use brevity codes where applicable. If you must transmit, switch to the alternate frequency specified in your communication plan. Radio silence will be lifted at twenty-two-hundred hours. Acknowledge this message with a single key click. Do not use voice acknowledgment.", question: "How should stations acknowledge this directive?", options: ["By transmitting a brief voice confirmation on the primary frequency.", "By switching to the alternate frequency and reporting readiness.", "By pressing the transmit button once without speaking.", "By maintaining silence until twenty-two-hundred hours."], answer: 2, ex: "'Acknowledge this message with a single key click. Do not use voice acknowledgment' — option C paraphrases 'single key click' as 'pressing transmit button once' and captures the no-voice instruction as 'without speaking'. A directly contradicts the instruction. B adds an action not requested. D misunderstands (acknowledgment IS required, just not vocally). The detail is easy to miss in a longer passage, testing sustained attention." },
    { topic: "Communication equipment failure", passage: "Attention all units. Primary communication system is experiencing intermittent failures. Maintenance teams are working to resolve the issue. Estimated restoration time is four hours. In the meantime, use the backup radio network for all operational communications. The backup network operates on frequencies published in communication annex three of your operations order. If you cannot access the backup network, report to your parent headquarters by any means available including messenger. Priority messages should be sent using multiple methods to ensure delivery.", question: "What should units do if the backup network is also unavailable to them?", options: ["Wait for the primary system to be restored before transmitting messages.", "Attempt to repair their radio equipment using available maintenance resources.", "Restrict communications to emergency situations only until systems are restored.", "Contact their headquarters through any alternative method including physical courier."], answer: 3, ex: "'If you cannot access the backup network, report to your parent headquarters by any means available including messenger' — option D paraphrases 'any means available including messenger' as 'any alternative method including physical courier'. A contradicts the instruction (don't wait; use any means). B is not mentioned. C adds a restriction not stated. The question tests whether listeners caught contingency planning buried mid-passage." },
    { topic: "Community engagement guidance", passage: "Guidance for all personnel conducting civil-military operations. Interactions with local populations should be respectful and professional. If civilians approach you with requests for assistance, listen to their concerns and note them for reporting to the civil affairs team. Do not make promises of specific assistance on behalf of the military. Instead, explain that their request will be forwarded to appropriate personnel for consideration. Maintain courtesy even if you cannot provide immediate help. Remember that every interaction shapes local perceptions of our mission.", question: "How should personnel respond to civilian requests for assistance?", options: ["Record the requests and explain they will be forwarded for assessment.", "Provide immediate assistance for minor requests and document major ones.", "Refer all requests directly to local government officials for resolution.", "Politely decline requests and explain that assistance is beyond their authority."], answer: 0, ex: "'Note them for reporting to the civil affairs team' and 'explain that their request will be forwarded to appropriate personnel for consideration' — option A synthesizes both actions: record + explain forwarding. B introduces a distinction (minor vs major) not made in the guidance. B isn't mentioned (requests go to civil affairs, not local government). D is too negative (the guidance is to acknowledge requests will be considered, not to decline them). The skill: combining two related instructions." },
    { topic: "Damage compensation procedures", passage: "Procedures for reporting property damage claims. If local civilians report damage they believe was caused by military operations, direct them to the civil affairs office located at the main base. The office is open daily from oh-eight-hundred to sixteen hundred except Sundays. Claimants must bring documentation if available, such as photographs or witness statements. Claims must be filed within thirty days of the incident. Explain these procedures clearly but do not offer opinions on whether a claim will be approved. Claims processing typically takes four to six weeks.", question: "What information should personnel provide to civilians making damage claims?", options: ["An estimate of how long their claim will take to be approved or denied.", "Instructions on where to file the claim and what documentation to bring.", "Assurance that legitimate claims will be compensated within thirty days.", "The name and contact information of the claims processing officer."], answer: 1, ex: "Personnel should 'direct them to the civil affairs office' (where), 'office is open daily from oh-eight-hundred to sixteen hundred' (when), and 'bring documentation if available' (what). Option B captures the essential information: where to file + what to bring. A is wrong (personnel should not offer opinions on approval). C misreads the 30-day deadline (that's for filing, not processing). D isn't mentioned. The question tests synthesis of procedural information spread across the passage." },
    { topic: "Range safety briefing", passage: "Safety briefing for today's live-fire exercise. The range is hot from oh-nine-hundred to twelve hundred. All personnel not participating in the exercise must remain clear of the range safety area marked by red flags. If you hear three short whistle blasts, cease fire immediately and make your weapon safe. This is the emergency stop signal. Any safety violation will result in immediate termination of the exercise. Eye and ear protection is mandatory for all personnel on the range. Medical support is positioned at the range control point. Questions before we begin?", question: "What does the three-whistle signal indicate?", options: ["The scheduled exercise time has concluded and personnel may leave the range.", "Medical support is needed at the range control point.", "A safety emergency requiring immediate cessation of all firing.", "Personnel not involved in the exercise should clear the safety area."], answer: 2, ex: "'If you hear three short whistle blasts, cease fire immediately' + 'This is the emergency stop signal' — option C paraphrases this as 'safety emergency requiring immediate cessation of all firing'. A is wrong (scheduled conclusion is 12:00, not signaled by whistle). B misreads (medical support is mentioned separately). D refers to a different safety measure (staying clear of flagged area). The question tests recall of emergency signals within safety procedures." },
    { topic: "Physical training safety", passage: "Physical training guidance for this week. Due to elevated temperatures, all organized physical training will begin at oh-six-hundred rather than the usual oh-seven-hundred. Session duration will be reduced from ninety minutes to sixty minutes. Personnel should consume at least half a liter of water before training begins. Trainers will allow a two-minute water break every fifteen minutes. If any individual shows signs of heat distress, stop the session immediately and notify medical personnel. Do not attempt to continue training through early symptoms.", question: "What change has been made to the physical training schedule?", options: ["Training duration has been cut in half to reduce heat exposure.", "Personnel must now consume water every fifteen minutes during training.", "Physical training is suspended until temperatures return to normal levels.", "Sessions will start one hour earlier and finish thirty minutes sooner than usual."], answer: 3, ex: "Start time changed from 07:00 to 06:00 (one hour earlier); duration reduced from 90 minutes to 60 minutes (30 minutes shorter). Option D captures both changes. B overstates (from 90 to 60 is not half; it's one-third reduction). B misreads (water breaks every 15 minutes, not consumption requirement). C contradicts the passage (training continues with modifications). The question tests whether listeners integrated two separate time changes." }
  ],
  3: [
    { topic: "NATO summit — deterrence posture briefing", passage: "Ladies and gentlemen, the summit communiqué reaffirms the alliance's commitment to collective defence under Article Five, while also emphasising the importance of burden sharing among member nations. There is growing consensus that defence spending should reach two percent of gross domestic product as a minimum, with several allies now committing to exceed this threshold. Of particular significance is the agreement to establish a new rapid reaction capability on the eastern flank, comprising pre-positioned equipment and a rotational troop presence. This represents a fundamental shift from the reassurance model to an enhanced deterrence posture. The implications for force planning will be substantial.", question: "What does the agreement on a rapid reaction capability in the east represent?", options: ["Implementation of the two-percent GDP defence-spending target", "A renewal of Cold-War-era forward defence arrangements", "A move beyond demonstrating commitment toward a more credible deterrent stance", "A new framework consolidating burden-sharing negotiations"], answer: 2, ex: "本文の 'a fundamental shift from the reassurance model to an enhanced deterrence posture' を 'beyond demonstrating commitment toward a more credible deterrent stance' とパラフレーズ。'reassurance' → 'demonstrating commitment'、'enhanced deterrence' → 'more credible deterrent stance'。B は本文の別話題 (GDP) と混同を狙った distractor、C は 'Cold War' という本文にない時代設定で誇張、D は 'burden sharing' を中心の動きと取り違えさせる。L3 では同義語認識が鍵。" },
    { topic: "Logistics conference — fuel vulnerability", passage: "Fuel consumption remains our greatest logistical vulnerability. In the current operational context, forward bases are consuming an average of twelve thousand litres of diesel per day, the majority of which is used for power generation rather than vehicle movement. Reducing this dependency requires both short-term solutions, such as improved generator efficiency, and longer-term investment in renewable energy sources. Solar installations at two forward bases have already reduced fuel demand by approximately eighteen percent, and we are planning to expand this initiative across all fixed installations within the next fiscal year.", question: "What has been the effect of solar installations at forward bases?", options: ["They have removed diesel reliance altogether at two trial locations", "They have already been deployed at every fixed installation", "They have raised vehicle fuel economy under combat conditions", "They have measurably curbed the bases' diesel requirement"], answer: 3, ex: "本文の 'reduced fuel demand by approximately eighteen percent' を 'measurably curbed the bases' diesel requirement' とパラフレーズ (具体数を含めず、概念で言い換え)。A は 'reduced' を 'removed altogether' と誇張、B は 'planning to expand' をすでに完了したかのように歪曲、D は power generation 用途を vehicle 用途に置き換える誤り。L3 では誇張・歪曲の検出が鍵。" },
    { topic: "Media operations — press guidance briefing", passage: "Listen carefully. The commander's press statement will be released at fourteen hundred. Key messages are as follows. First, that all military actions have been conducted in full compliance with international law. Second, that civilian protection has been the paramount concern throughout the operation. Third, that we are working closely with humanitarian organisations to facilitate access to affected populations. You are not authorised to comment on operational timelines, casualty figures, or future intentions. Refer all media queries outside these key messages to the public affairs officer.", question: "What are personnel instructed NOT to comment on?", options: ["Mission scheduling, loss numbers, and plans yet to be executed", "The lawful conduct of the operation", "The number of troops currently deployed", "The status of cooperation with humanitarian organisations"], answer: 0, ex: "本文の 'operational timelines, casualty figures, or future intentions' をそれぞれ 'mission scheduling'、'loss numbers'、'plans yet to be executed' とパラフレーズ。B/D は本文では「コメント可」の key messages として挙げられているため逆。C は本文に該当記述なし — もっともらしい distractor。L3 では 3 項目すべてを 1 つの選択肢で正確に言い換えているか判別する。" },
    { topic: "Strategic assessment briefing", passage: "Good afternoon. The strategic assessment for the current quarter identifies three principal challenges. First, the deterioration of the security environment along the eastern flank requires sustained military presence and enhanced deterrence measures. Second, hybrid threats targeting critical infrastructure have intensified and demand integrated civilian-military responses. Third, the strain on logistical systems caused by simultaneous operations in multiple theatres approaches the limits of current capacity. Resource allocation decisions must reflect these realities. The full report will be distributed by close of business tomorrow.", question: "What does the assessment identify regarding logistical systems?", options: ["They retain comfortable slack relative to demand", "Parallel commitments in several regions are pushing them near their ceiling", "They are operating well within design parameters", "They have undergone a comprehensive restructuring"], answer: 1, ex: "本文の 'strain on logistical systems caused by simultaneous operations in multiple theatres approaches the limits of current capacity' を 'parallel commitments in several regions are pushing them near their ceiling' とパラフレーズ。A/C は逆方向の楽観評価、D は本文に該当記述のない誤読。L3 では capacity / strain といった抽象語の言い換え認識が試される。" },
    { topic: "Doctrine update briefing", passage: "Recent operational experience has prompted significant revisions to alliance doctrine. The updated framework emphasises the integration of conventional, cyber, and information capabilities within unified operational concepts. National forces will be expected to develop competence across these domains rather than focusing narrowly on traditional military skills. Implementation will require investment in training, equipment, and personnel selection criteria. The transition timeline extends over five years, with initial certification of integrated units expected within eighteen months. Member nations are requested to identify lead units for participation in the certification programme.", question: "What capability profile will national forces be expected to develop under the updated doctrine?", options: ["Mastery of conventional skills with cyber and information matters delegated to specialists", "An exclusive focus on emerging cyber and information capabilities", "A broad fluency across conventional, cyber, and information domains alike", "Maintenance of the existing narrow specialisation framework"], answer: 2, ex: "本文の 'develop competence across these domains rather than focusing narrowly on traditional military skills' と 'integration of conventional, cyber, and information capabilities' から、3 領域への広汎な熟達が要求されている。A は分業を主張する逆の構造、C は cyber/info 一辺倒で 'conventional' を捨てる誤読、D は本文が明確に否定する旧体制。L3 では integration / convergence の概念把握が鍵。" },
    { topic: "Counter-terrorism analysis", passage: "The counter-terrorism analysis for this quarter highlights an evolving threat picture. Established networks have been substantially degraded through sustained pressure. However, the diffusion of operational capabilities has produced an increase in attacks by individuals or small cells with limited prior connections to organised groups. These actors typically employ readily available means and target locations selected for symbolic rather than strategic value. Detection and prevention require enhanced cooperation between intelligence and law enforcement agencies, supported by community engagement initiatives. Purely military responses are insufficient to address the contemporary threat.", question: "What does the analysis say about purely military responses?", options: ["They remain the single most effective tool against the current threat", "They warrant a significant expansion of resources and authority", "They have ceased to be relevant in any counter-terrorism context", "They fall short of what the present threat environment demands"], answer: 3, ex: "本文の 'Purely military responses are insufficient to address the contemporary threat' を 'fall short of what the present threat environment demands' とパラフレーズ。A/B は本文の論調と逆、D は 'insufficient' を 'ceased to be relevant' と過度に拡張した誤読。L3 では 'insufficient' と 'irrelevant' の意味差を見抜く必要あり。" },
    { topic: "Allied cooperation briefing", passage: "Today's briefing addresses recent developments in allied cooperation. The integration of Finland and Sweden into alliance structures has progressed substantially over the past year. Force contributions, planning processes, and command arrangements have been updated to reflect their full participation. The strategic implications, particularly for operations in the Baltic and Arctic regions, are profound. Our planning assumptions require revision to account for the expanded operational geography and the additional capabilities now available to the alliance. Specific guidance for affected commands will follow this briefing.", question: "What does the briefing identify as requiring revision?", options: ["The baseline premises underlying alliance planning", "The text of the founding treaty itself", "National defence appropriations", "Standing recruitment and selection procedures"], answer: 0, ex: "本文の 'Our planning assumptions require revision' を 'baseline premises underlying alliance planning' とパラフレーズ。B は 'treaty' という本文にない上位文書、C/D は本文に該当記述なし — もっともらしいが論点ではない distractor。L3 では 'planning assumptions' という抽象概念の同義語認識が問われる。" },
    { topic: "Cyber incident briefing", passage: "Yesterday at twenty-three hundred, a cyber incident affecting our administrative networks was detected. Initial analysis indicates a sophisticated intrusion using techniques consistent with state-sponsored activity. Sensitive operational systems remained isolated and unaffected. The full extent of compromise is still being determined. Mitigation measures are in place. We expect operational impact to be minimal, although some administrative functions will operate at reduced efficiency for several days. Detailed technical briefings will be provided to affected units this afternoon.", question: "What is the expected operational impact?", options: ["Severe disruption lasting weeks", "Negligible, with only ancillary back-office slowdowns", "Indeterminate pending forensic analysis", "Confined to front-line combat units"], answer: 1, ex: "本文の 'operational impact to be minimal, although some administrative functions will operate at reduced efficiency' を 'negligible, with only ancillary back-office slowdowns' とパラフレーズ。A は誇張、C は本文 'expect... to be minimal' という確定的表現と矛盾、D は operational と combat の対象範囲を逆転している誤読。L3 では二重情報 (主要影響 + 副次影響) の整理が試される。" },
    { topic: "Force generation briefing", passage: "The force generation conference identified shortfalls in three key capability areas. Combat support, particularly engineering and logistics, remains undermanned across multiple operations. Air mobility assets are committed at unsustainable levels with limited reserve capacity. Specialised personnel for emerging domains, including cyber and space operations, are in critically short supply. Member nations have been requested to review their contributions and identify potential additional commitments. The next force generation conference is scheduled for the autumn, when revised commitments will be consolidated.", question: "Which capability category is described as deployed beyond a sustainable rate?", options: ["Engineering and logistics combat support", "Cyber and space personnel for emerging domains", "Strategic and tactical airlift", "Reserve formations awaiting activation"], answer: 2, ex: "本文の 'Air mobility assets are committed at unsustainable levels' を 'strategic and tactical airlift' とパラフレーズ ('air mobility' = airlift / 戦略・戦術空輸)。A は undermanned とされる別カテゴリ、B は in short supply とされる別カテゴリで紛らわしさを増した distractor、D は本文に該当記述なし。L3 では 3 つの shortfall を混同せず正しく対応させる力が問われる。" },
    { topic: "Strategic partnership briefing", passage: "Strategic partnerships beyond the alliance continue to evolve in response to changing security dynamics. Cooperation with the Indo-Pacific democracies has expanded substantially, reflecting growing recognition of interconnected security challenges. Joint exercises, intelligence sharing, and dialogue mechanisms have been established or enhanced. Critics caution that overextension of alliance attention beyond the Euro-Atlantic area risks dilution of focus from primary collective defence responsibilities. Proponents argue that contemporary security cannot be neatly compartmentalised and that engagement with global partners enhances rather than detracts from regional security commitments.", question: "What argument do proponents of expanded global partnerships make?", options: ["Attention should be confined to the Euro-Atlantic region", "Cooperation should be restricted to a narrow military scope", "Indo-Pacific engagement has produced disappointing results", "Distant partnerships strengthen rather than weaken regional security"], answer: 3, ex: "本文の 'engagement with global partners enhances rather than detracts from regional security commitments' を 'distant partnerships strengthen rather than weaken regional security' とパラフレーズ。A は批判側 (critics) の主張、B/C は本文に該当記述のない distractor。L3 では 'enhance/detract' / 'strengthen/weaken' といった対比表現の同義語認識が問われる。" },
    { topic: "Capability development update", passage: "Capability development priorities for the coming period focus on resilience, advanced technology integration, and force readiness. Resilience improvements address vulnerabilities exposed by recent crises, including supply chain dependencies and critical infrastructure protection. Advanced technology integration emphasises artificial intelligence applications, autonomous systems, and quantum-enabled capabilities. Force readiness measures aim to reduce response timelines for high-readiness units. Resource constraints require careful prioritisation among these competing demands. Member nations are encouraged to align national capability development with these alliance priorities.", question: "What category of weakness do the resilience efforts target?", options: ["Exposures in procurement pipelines and the safeguarding of essential utilities", "Hardware reliability shortcomings in fielded combat platforms", "Gaps in basic and advanced personnel training programmes", "Obsolescence of tactical radio communications equipment"], answer: 0, ex: "本文の 'supply chain dependencies and critical infrastructure protection' を 'procurement pipelines' / 'safeguarding of essential utilities' とパラフレーズ。B は技術統合 (AI/自律システム) の話と混同を誘う distractor、C/D は本文に該当記述なし。L3 では supply chain / critical infrastructure という抽象語の含意理解が試される。" },
    { topic: "Operational risk assessment", passage: "The current operational risk assessment identifies elevated probability of incidents involving multiple actors in contested operational environments. Deconfliction mechanisms remain essential to prevent inadvertent escalation. Recent incidents involving close approaches between alliance and adversary forces have underscored the importance of clear procedures and rapid communication. Risk mitigation requires both technical measures, including improved identification systems, and procedural measures including agreed protocols for unplanned encounters. Training emphasis on these procedures has been increased across affected units.", question: "What does the assessment treat as indispensable?", options: ["A larger forward military presence in contested zones", "Arrangements that keep parallel operations from spiralling into unintended conflict", "Pulling alliance forces back from disputed areas", "High-profile public diplomatic statements"], answer: 1, ex: "本文の 'Deconfliction mechanisms remain essential to prevent inadvertent escalation' を 'arrangements that keep parallel operations from spiralling into unintended conflict' とパラフレーズ。A/D は本文に該当記述なし、C は本文と逆 (退避ではなく現場での仕組み整備が要)。L3 では deconfliction という専門用語を平易な英語で言い換えて理解しているか試される。" },
    { topic: "Logistics modernisation briefing", passage: "Logistics modernisation initiatives address persistent challenges identified during recent operations. The current system, characterised by national stovepipes and limited interoperability, generates inefficiencies and creates vulnerabilities. Multinational logistics arrangements offer significant potential improvements but require political commitment from contributing nations. The pilot programme launched last year demonstrated achievable cost savings of approximately fifteen percent through pooled supply arrangements. Expansion of the pilot to additional categories of equipment is under active consideration. Implementation challenges include reconciling different national procurement procedures and quality standards.", question: "What was the principal finding of the pilot programme?", options: ["Multinational arrangements proved unworkable in practice", "Each nation should retain its own independent supply chain", "Pooling deliveries across nations yielded a meaningful reduction in expenditure", "Shared inventories suffered from inconsistent quality"], answer: 2, ex: "本文の 'cost savings of approximately fifteen percent through pooled supply arrangements' を 'pooling deliveries across nations yielded a meaningful reduction in expenditure' とパラフレーズ (具体数値ではなく概念で言い換え)。A/D は本文の論調と逆、B は modernisation の方向と逆。L3 では数値そのものではなく結論の意味を捉える力が問われる。" },
    { topic: "Information environment briefing", passage: "The information environment continues to be a critical dimension of contemporary operations. Adversary information activities target alliance cohesion, undermine public support for military engagements, and create operational uncertainty. Effective response requires both reactive capabilities, including rapid fact-checking and counter-messaging, and proactive measures including narrative shaping and resilience building. Our democratic values impose constraints on certain types of information activities that authoritarian adversaries do not face. These constraints must be respected even as we develop more effective approaches within them. Strategic communications competence is now considered essential at all command levels.", question: "What does the briefing say about democratic values?", options: ["They have no bearing on how information operations are conducted", "They are impediments that must be circumvented for operational effect", "They are an outdated framework no longer fit for current conditions", "They mark limits we must honour even while seeking sharper tools within them"], answer: 3, ex: "本文の 'These constraints must be respected even as we develop more effective approaches within them' を 'mark limits we must honour even while seeking sharper tools within them' とパラフレーズ。A は本文と逆、B は 'respected' を 'circumvented' と反転、C は本文に該当記述なし。L3 では 'constraints' / 'limits' / 'must be respected' / 'must honour' といった同義表現を捕捉する力が問われる。" },
    { topic: "Future force concept briefing", passage: "The future force concept envisions integrated operations across all domains, supported by ubiquitous data sharing and artificial intelligence-enabled decision support. Human-machine teaming will become increasingly central to operational effectiveness. Traditional distinctions between combat and support functions will blur as automation reshapes operational tasks. Personnel skills must evolve correspondingly, with technical literacy required across all roles. Training systems require fundamental redesign to develop and maintain these new competencies. Investment in this transformation cannot be delayed without accepting growing capability gaps relative to potential adversaries.", question: "What does the concept say about traditional combat-support distinctions?", options: ["The line dividing them will grow indistinct as automation reshapes tasks", "They will be drawn even more sharply than at present", "They will be done away with completely", "They will persist in their current form"], answer: 0, ex: "本文の 'Traditional distinctions between combat and support functions will blur as automation reshapes operational tasks' を 'the line dividing them will grow indistinct as automation reshapes tasks' とパラフレーズ。B は逆方向、C は 'blur' を 'eliminate entirely' と過度に拡張、D は現状維持で本文と矛盾。L3 では 'blur' = 'grow indistinct' の同義語認識が試される。" },
    { topic: "Operational lessons learned — after action review", passage: "Good morning. I'm here to present findings from the after action review of last month's operation. Overall, mission objectives were achieved. However, several areas require attention. First, coordination between ground and air elements experienced delays averaging forty minutes, primarily due to communication challenges. While our equipment functioned properly, procedural differences between services created confusion during time-critical phases. Second, logistical planning underestimated fuel consumption by approximately eighteen percent. This forced mid-operation adjustments that, while successful, reduced operational tempo. Third, intelligence support was generally adequate, but there were gaps in our understanding of civilian movement patterns, which complicated our efforts to minimize disruption to local populations. On the positive side, the multinational composition of the force proved highly effective, and liaison arrangements worked well. The key lesson is that technical interoperability is necessary but insufficient. We need better harmonization of procedures and more realistic planning assumptions. Full report with recommendations will be distributed by Friday.", question: "What does the presenter suggest about equipment versus procedures?", options: ["Equipment failures were the primary cause of coordination delays.", "Even when equipment works properly, procedural differences can create problems.", "Procedural harmonization should take priority over equipment improvements.", "Equipment and procedures both require significant overhaul."], answer: 1, ex: "'While our equipment functioned properly, procedural differences between services created confusion' — option B captures the contrast: equipment OK, procedures problematic. A contradicts the statement about equipment functioning. C makes a priority claim not stated (both matter; the point is procedures caused the observed delays despite working equipment). D overstates (procedural improvement is needed; equipment overhaul is not mentioned). The inference skill: recognizing a 'necessary but insufficient' argument structure." },
    { topic: "Force posture assessment — strategic analysis", passage: "This briefing examines our force posture in the region. Current deployments reflect threat assessments made three years ago. Since then, the security environment has shifted. We now face a more diverse range of potential challenges, including hybrid threats that blur traditional distinctions between peace and conflict. Our current posture, optimized for conventional deterrence, may be less effective against these newer threat forms. However, reshaping our presence involves trade-offs. Increasing rotational deployments enhances flexibility but reduces the stability that comes from permanent presence. Forward positioning of additional capabilities improves response times but increases sustainment costs and creates new vulnerabilities. Moreover, any significant changes must be coordinated with host nations, whose domestic political considerations may not align perfectly with our strategic preferences. The recommendation is therefore not radical restructuring but rather incremental adjustments that preserve core deterrence while building capacity to address emerging challenges. This approach balances operational effectiveness with political sustainability.", question: "What principle guides the recommended approach to adjusting force posture?", options: ["Dramatic changes are necessary to address the fundamentally altered threat environment.", "Political considerations should take precedence over operational military requirements.", "Gradual modifications that maintain deterrence while addressing new threats.", "Rotational deployments should replace permanent presence to maximize flexibility."], answer: 2, ex: "'The recommendation is... not radical restructuring but rather incremental adjustments that preserve core deterrence while building capacity to address emerging challenges' — option C paraphrases 'incremental adjustments' as 'gradual modifications' and captures the dual objectives. A contradicts 'not radical restructuring'. B oversimplifies (the approach balances both, doesn't prioritize one). D is one potential tool mentioned, not the guiding principle. The skill: identifying the synthesis position that acknowledges competing considerations." },
    { topic: "Intelligence assessment — pattern analysis", passage: "Intelligence assessment for the commander. Over the past six weeks, we've observed three distinct patterns. First, increased surveillance of our installations, conducted by individuals who disperse when challenged rather than engaging. Second, probing attacks on outlying positions, limited in scope and quickly broken off. Third, a marked increase in propaganda efforts targeting local populations. Taken individually, each pattern has innocent explanations. Surveillance could be journalistic. Probing attacks might be opportunistic. Propaganda is constant background noise. However, the convergence of all three suggests more deliberate preparation. Historical precedent indicates that this combination precedes escalation in approximately seventy percent of similar situations. That said, we must avoid mirror imaging. Our adversary's decision calculus may differ from historical patterns. Recommend enhanced defensive preparations without provocative forward actions that could become self-fulfilling prophecy. Maintain intelligence collection at current intensity. Next assessment in seven days or sooner if patterns intensify.", question: "Why does the intelligence officer recommend enhanced defensive measures?", options: ["Because each individual pattern definitively indicates imminent attack.", "Because the adversary's propaganda has been particularly effective.", "Because surveillance, attacks, and propaganda each require separate responses.", "Because historical data shows this combination often precedes escalation."], answer: 3, ex: "'The convergence of all three suggests more deliberate preparation' + 'Historical precedent indicates that this combination precedes escalation in approximately seventy percent of similar situations' — option D captures the probabilistic reasoning. A is contradicted ('Taken individually, each pattern has innocent explanations'). C focuses on one element rather than the pattern convergence. C misses the analytical point (it's the combination that matters). The Level 3 skill: following probabilistic reasoning and pattern-based inference." },
    { topic: "Civil-military coordination — policy guidance", passage: "Policy guidance on civil-military operations. Our mission includes both security tasks and support to civilian authorities. These objectives can come into tension. Security operations may require restricting movement, which disrupts economic activity and generates friction with local populations. Conversely, being too accommodating may create exploitable seams that adversaries use. The guidance is to prioritize security requirements when genuine threats exist, but to be minimally intrusive in implementation. This means using checkpoints strategically rather than comprehensively, and adjusting security measures based on current threat levels rather than applying maximum measures continuously. Engagement with civilian leaders should be frequent and substantive. Explain why security measures are necessary and be willing to adjust them when concerns are raised, provided security is not compromised. Remember that local populations are not the threat. They are the reason we're here. Their cooperation is itself a security asset. Alienating them makes our mission harder, not safer.", question: "What assumption underlies the guidance to maintain local cooperation?", options: ["That civilian cooperation contributes to achieving security objectives.", "That security threats originate primarily from outside the local population.", "That military forces lack the authority to impose restrictions on local populations.", "That adjusting security measures demonstrates weakness to potential adversaries."], answer: 0, ex: "'Their cooperation is itself a security asset. Alienating them makes our mission harder, not safer' — option A paraphrases the idea that cooperation helps achieve security. B is partially implied but overstates the categorical claim (the text says populations aren't the threat, not that threats come from outside). C is wrong (forces can restrict movement; the guidance is about being minimally intrusive). D reverses the logic. The Level 3 skill: identifying implicit assumptions underlying stated policy." },
    { topic: "Training doctrine discussion — skill development", passage: "Training doctrine discussion. There's ongoing debate about whether training should emphasize rehearsal of specific tactics and procedures versus developing broader adaptive thinking. The rehearsal approach produces standardized responses that work well in predictable environments. Units drilled in specific procedures can execute them rapidly under stress. However, adversaries study our procedures and design countermeasures. Moreover, operational environments are often unpredictable. The adaptive approach emphasizes decision-making skills and the ability to devise solutions to novel problems. This flexibility is valuable but harder to assess and takes longer to develop. Units may be less polished in execution because they're practicing principles rather than specific drills. In reality, we need both. The question is emphasis and sequencing. My view is that basic training should focus on procedural mastery. This builds confidence and ensures minimum standards. Advanced training should then develop adaptive capacity, using the procedural foundation as a starting point for variation and improvisation. This progression from structured to flexible training aligns with how expertise develops in other complex domains.", question: "How does the speaker propose to resolve the training debate?", options: ["By abandoning procedural training in favor of purely adaptive approaches.", "By using procedural training as a foundation, then building adaptive skills at advanced levels.", "By having different units specialize in either procedural or adaptive methods.", "By emphasizing adaptive training since adversaries can counter known procedures."], answer: 1, ex: "'Basic training should focus on procedural mastery... Advanced training should then develop adaptive capacity, using the procedural foundation as a starting point' — option B captures the sequential integration. A and D take one side of a false binary. C proposes specialization not mentioned. The speaker explicitly says 'we need both' and proposes a developmental sequence. The Level 3 skill: recognizing synthesis positions that integrate seemingly opposed views." },
    { topic: "Multinational command arrangements — political constraints", passage: "Command arrangements in multinational operations present unique challenges. In theory, unity of command produces the most effective military outcomes. A single commander with full authority can make rapid decisions and ensure coherent action. In practice, unity of command often gives way to consensus-based arrangements because contributing nations retain ultimate authority over their forces. This reflects political reality, not military preference. National governments remain accountable to their domestic constituencies and cannot surrender decision-making authority entirely to international commands. The result is that operational plans must accommodate national caveats and decisions sometimes take longer than purely military logic would suggest. However, this political constraint is also the foundation of alliance cohesion. Nations contribute forces precisely because they trust their concerns will be heard. Attempting to override national prerogatives might gain short-term operational efficiency but risks undermining the long-term political basis for cooperation. Effective multinational command therefore requires continuous negotiation, transparency about constraints, and creative problem-solving to achieve objectives within political boundaries.", question: "What does the speaker suggest about the trade-off between military efficiency and political sustainability?", options: ["Military efficiency should always take priority in operational contexts.", "Political sustainability is more important than operational effectiveness.", "Short-term operational gains may come at the cost of long-term cooperation.", "Nations should surrender more authority to achieve unity of command."], answer: 2, ex: "'Attempting to override national prerogatives might gain short-term operational efficiency but risks undermining the long-term political basis for cooperation' — option C directly captures this trade-off. A and B make absolute priority claims the speaker rejects (both matter). D contradicts the speaker's acceptance of political reality. The Level 3 skill: understanding temporal trade-offs (short-term vs. long-term)." },
    { topic: "Logistics vulnerability assessment", passage: "Logistics vulnerability assessment. Current supply chains involve multiple potential points of failure. Fuel convoys travel predictable routes on known schedules. Storage depots are fixed locations. Communication systems coordinating logistics use detectable electronic signatures. Adversaries have demonstrated capability and willingness to target these vulnerabilities. Three approaches to risk reduction are under consideration. First, hardening defenses at fixed sites through additional security measures and fortification. Second, making convoys less predictable through varied routes and timing. Third, reducing overall dependence on vulnerable supply lines by positioning more stocks forward or using alternative technologies like renewable energy. Each approach has advantages and costs. Hardening is effective but resource-intensive. Variation reduces predictability but complicates planning. Forward positioning reduces convoy requirements but increases stocks at risk if forward positions are overrun. The assessment concludes that a layered strategy combining all three approaches provides better risk management than relying on any single method. Diversification of defensive measures creates resilience.", question: "What rationale does the assessment provide for using multiple approaches?", options: ["Because resource constraints prevent full implementation of any single approach.", "Because different approaches can be assigned to different types of supply missions.", "Because combining methods confuses adversaries about which defensive measures to counter.", "Because no individual method addresses all vulnerabilities adequately."], answer: 3, ex: "'A layered strategy combining all three approaches provides better risk management than relying on any single method. Diversification of defensive measures creates resilience' — option D captures the inadequacy of single methods. A is unmentioned (resources aren't cited as the driver). B misreads (it's about layering, not assigning different approaches to different missions). C is plausible but not stated. The inference: 'provides better risk management' implies individual methods are insufficient." },
    { topic: "Technology adoption — implementation challenges", passage: "Briefing on autonomous systems integration. These technologies offer significant potential benefits including reduced risk to personnel and improved mission effectiveness. However, adoption faces several challenges beyond the purely technical. First, personnel who currently perform tasks that might be automated may resist changes that they perceive as threatening their roles. This is natural human response to technological change. Second, over-reliance on automated systems could atrophy skills that might be needed if systems fail or are compromised. We've seen this pattern in other domains where automation replaced human capability. Third, legal and ethical frameworks for autonomous systems in military operations remain unsettled. Using such systems without clear rules could create legal exposure. The recommendation is phased adoption. Introduce autonomous systems for specific well-defined tasks, maintain parallel human capabilities during transition, and develop doctrine and legal guidance alongside technical deployment. This measured approach allows us to gain benefits while managing risks and building institutional acceptance.", question: "Why does the briefing recommend phased rather than rapid adoption?", options: ["Because multiple non-technical concerns require time to address properly.", "Because autonomous systems have not yet demonstrated sufficient technical reliability.", "Because personnel resistance must be overcome through gradual familiarization.", "Because legal frameworks prohibit full autonomous system deployment currently."], answer: 0, ex: "The briefing identifies personnel resistance, skill atrophy risk, and legal uncertainty as challenges, then recommends phased adoption to 'manage risks and build institutional acceptance'. Option A captures the multiple concerns requiring time. B is wrong (technical potential is affirmed). C focuses on one factor (resistance) but misses legal/skill issues. D overstates (frameworks are 'unsettled', not prohibitive). The skill: recognizing when multiple independent concerns justify a cautious approach." },
    { topic: "Strategic partnership assessment", passage: "Assessment of strategic partnerships. Our partnerships with non-member countries serve multiple functions. They build interoperability for potential coalition operations. They project stability into neighboring regions. They demonstrate alliance openness to cooperation beyond formal membership. However, partnerships face growing complications. Some partners face domestic political pressure from constituencies that view close association with the alliance as compromising sovereignty. Other partnerships are strained by partners developing alternative security relationships with powers whose interests sometimes diverge from ours. These tensions don't necessarily mean partnerships are failing. They reflect the reality that partners are sovereign nations with their own interests that don't always align perfectly with ours. The challenge is managing partnerships realistically rather than viewing them through an idealized lens. This means accepting that cooperation will vary across different issue areas and over time. It means maintaining dialogue even when disagreements arise. Most importantly, it means recognizing the distinction between formal partnership frameworks and the actual depth of cooperation sustainable given evolving political circumstances.", question: "What does the assessment suggest is necessary for effective partnership management?", options: ["Reducing the number of partnerships to focus on the most committed partners.", "Accepting that partnership cooperation will naturally fluctuate and vary.", "Requiring partners to choose between the alliance and alternative relationships.", "Developing more formal frameworks to institutionalize deeper cooperation."], answer: 1, ex: "'Managing partnerships realistically' includes 'accepting that cooperation will vary across different issue areas and over time' — option B captures this acceptance of natural variation. A is wrong (the passage doesn't advocate reduction). C contradicts accepting partners' sovereign interests. D misreads (the passage distinguishes frameworks from actual cooperation; more frameworks won't solve the political reality). The Level 3 skill: identifying pragmatic rather than idealized approaches." },
    { topic: "Information operations ethical guidance", passage: "Ethical guidance for information operations. Information has always been an element of conflict. What has changed is the speed, scale, and sophistication of information campaigns enabled by digital technology. We face adversaries who conduct large-scale disinformation operations designed to undermine our cohesion and erode public trust. Responding effectively is both operationally necessary and ethically complex. Countering false narratives with factual information is clearly appropriate. However, we must avoid mirroring adversary tactics. Using deception or manipulation, even against hostile actors, undermines the values we defend and erodes our own credibility over time. The guidance is therefore to counter disinformation through truth, not through reciprocal falsehoods. This may seem like fighting with one hand tied. The counterargument is that credibility is itself a strategic asset. Once lost, it's difficult to recover. Our commitment to truthfulness, even when adversaries show no such commitment, is not naïve idealism. It's recognition that legitimacy and trust are sources of power that deception inevitably erodes.", question: "What strategic logic does the speaker offer for maintaining truthfulness?", options: ["That international law prohibits deceptive information operations.", "That adversaries will reciprocate by reducing their own disinformation if we demonstrate restraint.", "That credibility represents a strategic advantage that deception would ultimately undermine.", "That democratic societies lack the institutional capacity to conduct effective deception."], answer: 2, ex: "'Credibility is itself a strategic asset. Once lost, it's difficult to recover' and 'legitimacy and trust are sources of power that deception inevitably erodes' — option C captures credibility as strategic advantage. A is not mentioned. B is contradicted (adversaries won't reciprocate). D is unmentioned. The speaker explicitly rejects the 'fighting with one hand tied' framing by arguing truthfulness IS strategically advantageous. The Level 3 skill: following an argument that values are strategic assets, not just ethical imperatives." },
    { topic: "Maritime security operations — Indo-Pacific transits", passage: "Today's brief covers freedom-of-navigation operations in the Indo-Pacific. Recent transits through contested waters have drawn vigorous rhetorical responses from regional powers, but no kinetic interference. This reflects deliberate calibration: presence sufficient to underscore legal positions, cadence and routing designed to avoid normalising escalation. Analytical attention is now turning to indirect consequences. Repeated transits anchor our diplomatic claims, but they also generate domestic political pressure on the very partners we hope to reassure, who can find themselves drawn into disputes they would rather sidestep. A second concern is interpretive: adversaries treat patterned transit as a planning input, allowing them to model our decision points. The recommendation is to introduce greater unpredictability in routing while preserving frequency, and to align diplomatic messaging more tightly with operational tempo so partners are not blindsided.", question: "What complication does the speaker raise beyond the immediate operational risks?", options: ["Allied navies cannot match the operational tempo current planning requires", "Adversary statements have escalated from rhetorical to outright kinetic responses", "Domestic political appetite for sustained naval presence is steadily eroding", "Partners can be pulled into disputes they would have preferred to avoid"], answer: 3, ex: "本文の 'partners we hope to reassure, who can find themselves drawn into disputes they would rather sidestep' を 'partners can be pulled into disputes they would have preferred to avoid' とパラフレーズ。B/D は本文に該当記述なし、C は本文の 'no kinetic interference' と矛盾。L3 では二次的影響の認識が問われる。" },
    { topic: "Arctic security architecture", passage: "Welcome to today's session on the changing Arctic security environment. The retreat of summer sea ice is opening shipping lanes that were impassable a decade ago and exposing seabed resources to commercial extraction. These developments are reshaping strategic calculations in ways the alliance has not previously had to confront. Three observations frame the issue. First, infrastructure on the Arctic littoral remains thin; even routine search-and-rescue capabilities lag behind anticipated traffic volumes. Second, several non-Arctic states are pursuing observer status in regional forums while building capabilities that would allow rather more than observation. Third, environmental sensitivities mean that incidents which would be diplomatically manageable elsewhere risk amplified consequences here. The implication is that capability development must proceed in parallel with norm-setting, since waiting for either to mature in isolation would leave the alliance reacting to events shaped by others.", question: "What does the speaker imply about Arctic capability development and norm-setting?", options: ["Both must advance in tandem to avoid being shaped by external actors", "Capability investment should be paused until governance arrangements stabilise", "Norm-setting will follow naturally once capabilities have matured sufficiently", "Search-and-rescue infrastructure is already adequate for projected traffic levels"], answer: 0, ex: "本文の 'capability development must proceed in parallel with norm-setting, since waiting for either to mature in isolation would leave the alliance reacting to events shaped by others' を 'both must advance in tandem to avoid being shaped by external actors' とパラフレーズ。A/C は逐次型を主張するが本文は並行が要、D は本文 'infrastructure... remains thin' と矛盾。" },
    { topic: "Space situational awareness briefing", passage: "Briefing on the deteriorating space situational awareness picture. The active satellite population has roughly tripled in the past five years, driven primarily by commercial constellations. Sensor capacity to track these objects has grown more slowly, and the catalogue of unidentified debris fragments now exceeds reliable identification capacity. The practical consequence is that our confidence in attributing any orbital incident to a specific actor has weakened, even as the strategic stakes of such incidents have risen. Two responses are being considered. The first is to invest heavily in additional ground- and space-based sensors. The second, less expensive but more politically sensitive, is to negotiate data-sharing agreements with commercial operators whose tracking ambitions exceed those of any single government. The two approaches are complementary, but the second offers near-term capacity gains that pure national investment cannot match within the relevant decision timelines.", question: "What advantage does the speaker attribute to the commercial-data approach?", options: ["It removes the strategic and political risks tied to ground-sensor procurement entirely", "It delivers usable capacity faster than national sensor investment alone can", "It guarantees full attribution of any orbital incident to a specific responsible actor", "It eliminates the need for further investment in any national space sensors going forward"], answer: 1, ex: "本文の 'the second offers near-term capacity gains that pure national investment cannot match within the relevant decision timelines' を 'delivers usable capacity faster than national sensor investment alone can' とパラフレーズ。A は本文 'more politically sensitive' と逆、B は 'confidence... has weakened' と矛盾、D は 'complementary' を置き換えと取り違える誤読。" },
    { topic: "Counter-intelligence threat assessment", passage: "Counter-intelligence assessment for the period. Insider threat indicators have shifted in two important ways. Traditional indicators — sudden lifestyle changes, unexplained foreign travel — remain valid but are less reliable now that financial and travel records are easier for adversaries to anticipate and obscure. Newer indicators centre on digital behaviour: anomalous credential use, irregular access patterns to sensitive systems, and attempts to consolidate information from compartments the individual would not normally combine. These signals are noisier than the classical ones; many false positives are generated by entirely innocent work patterns, and acting on them too readily creates serious morale and trust problems. The current recommendation is therefore graduated review rather than confrontation: increased passive monitoring, peer awareness training, and only then targeted inquiry. The procedural threshold for opening an inquiry must remain transparent to the workforce, since opacity here generates the very disaffection that produces insiders.", question: "Why does the assessment recommend a graduated rather than confrontational response?", options: ["Digital indicators have proven entirely unreliable for predicting insider behaviour patterns", "Adversaries have shown a markedly reduced interest in recruiting individuals as insiders", "Heavy-handed action on noisy signals would damage workforce trust and morale", "Traditional financial and travel indicators have been definitively superseded by digital ones"], answer: 2, ex: "本文の 'acting on them too readily creates serious morale and trust problems' を 'heavy-handed action on noisy signals would damage workforce trust and morale' とパラフレーズ。A は本文では 'noisier... but valid' で完全否定は誤読、B は本文に該当記述なし、C は本文 'remain valid' と矛盾。L3 では 'noisy signals' / 'graduated review' の抽象表現理解が試される。" },
    { topic: "Integrated air defence briefing", passage: "Discussion of integrated air defence in contested environments. The previous generation of architecture relied on hierarchical command, with engagement decisions concentrated at high echelons. This produced clean accountability but introduced decision latency that contemporary threats — particularly cruise missiles flying nap-of-the-earth profiles and swarms of low-cost drones — render unaffordable. The shift now under way distributes engagement authority to lower echelons and supports it with shared situational awareness derived from networked sensors. The trade-off is real. Distributed authority complicates deconfliction and increases the risk that two friendly elements engage the same target while genuine threats slip through gaps in coverage. Mitigation depends on rigorous battle drills and on a network whose redundancy survives the electromagnetic interference that adversaries will routinely impose. The doctrinal lesson is that speed of decision must be matched by discipline of execution; either alone is insufficient.", question: "What relationship does the speaker emphasise between decision speed and execution discipline?", options: ["Speed of decision should be prioritised since discipline can be added later in training", "Discipline of execution remains the only reliable safeguard in modern contested operations", "Distributed authority makes execution discipline largely redundant in current architectures", "Neither is sufficient by itself; both must be developed together"], answer: 3, ex: "本文の 'speed of decision must be matched by discipline of execution; either alone is insufficient' を 'neither is sufficient by itself; both must be developed together' とパラフレーズ。B/C は片方のみを優先する立場で本文と矛盾、D は本文 'depends on rigorous battle drills' と逆。" },
    { topic: "Special operations economy of force", passage: "Strategic review of special operations employment. The expansion of special forces over the past two decades has created a paradox. Units originally maintained for low-volume, high-stakes missions are now routinely assigned to roles that conventional forces could perform adequately, while the high-end missions for which they were optimised receive proportionally less rehearsal time. The opportunity cost is significant: rare expertise is being consumed in steady-state activities rather than reserved for the contingencies that justify the investment in the first place. Two corrective measures are under consideration. First, transferring partner-training missions to conventionally trained advisory units would free special operations capacity for unique tasks. Second, formalising a tiering system within the force itself would allow the most experienced operators to focus on contingency planning while less rare skill sets cover routine deployments. Both proposals face institutional resistance, but the alternative — continued consumption of strategic reserves on tactical demands — is not sustainable.", question: "What core problem does the review identify with current special operations use?", options: ["Scarce specialist capability is being expended on routine tasks rather than reserved for contingencies", "Conventional units are now competing directly with special forces for the same assignments globally", "Training cycles for special forces have been shortened below acceptable proficiency standards", "Partner-training missions have already been transferred away from special operations units"], answer: 0, ex: "本文の 'rare expertise is being consumed in steady-state activities rather than reserved for the contingencies' を 'scarce specialist capability is being expended on routine tasks rather than reserved for contingencies' とパラフレーズ。A は本文に該当記述なし、C は本文 'less rehearsal time' を縮めすぎた誇張、D は本文の 'under consideration' (検討中) を完了したかのように歪曲。" },
    { topic: "Strategic communications crisis response", passage: "Crisis communication planning brief. The first hour of any incident sets the narrative for everything that follows. Failure to provide an early authoritative statement does not buy time; it cedes the field to speculation that hardens before our own version can be assembled. This does not mean rushing to definitive claims that subsequent facts may contradict. The objective in the first hour is establishing presence and acknowledging the human dimension, not asserting full understanding of what occurred. Substantive details follow as they are confirmed. The discipline lies in distinguishing what is genuinely uncertain — and saying so — from what can be stated with confidence. Hedging on the latter to avoid commitment damages credibility as much as overclaiming on the former. Many of our worst recent communications outcomes have come not from saying the wrong thing but from saying nothing while alternative narratives consolidated.", question: "What does the speaker identify as the principal lesson from recent communications failures?", options: ["Spokespeople should never speak publicly until all facts have been fully verified", "Silence early in a crisis allows competing narratives to take hold", "Hedging is universally preferable to definitive statements during any active crisis", "Establishing presence requires presenting a complete account from the outset"], answer: 1, ex: "本文の 'our worst recent communications outcomes have come not from saying the wrong thing but from saying nothing while alternative narratives consolidated' を 'silence early in a crisis allows competing narratives to take hold' とパラフレーズ。A は 'cedes the field to speculation' と矛盾、B は 'hedging... damages credibility' と矛盾、D は 'not asserting full understanding' と矛盾。" },
    { topic: "Election interference defence", passage: "Briefing on the protection of democratic processes from foreign interference. Adversary activity targeting elections has matured beyond the crude approaches of earlier cycles. Volume-driven disinformation campaigns have largely given way to higher-quality content tailored to specific communities and amplified through compromised but ostensibly legitimate accounts. Detection therefore lags behind dissemination, and the damage from a single well-placed narrative can outweigh that of thousands of low-quality posts. Defensive emphasis is shifting accordingly. Less attention is being paid to total volumes of suspect content and more to the velocity with which specific narratives are reaching engaged audiences. Coordination with platform operators has improved, though it remains uneven and is constrained by legitimate concerns about government influence on private speech moderation. The persistent challenge is institutional: defensive responsibility is fragmented across agencies whose mandates were drafted before this threat category existed.", question: "What institutional weakness does the briefing identify in current defences?", options: ["Platform operators have effectively refused to engage with any government coordination effort", "Detection technology lags too far behind disinformation dissemination tools to be useful", "Defensive responsibilities are scattered across agencies whose remits predate the threat", "Volume-based monitoring has consistently proved more effective than narrative-based monitoring approaches"], answer: 2, ex: "本文の 'defensive responsibility is fragmented across agencies whose mandates were drafted before this threat category existed' を 'defensive responsibilities are scattered across agencies whose remits predate the threat' とパラフレーズ。A は 'coordination... has improved' と矛盾、B は本文に該当記述なし、C は 'less attention... volumes' と逆。" },
    { topic: "Energy security dependencies", passage: "Energy security assessment for the coming planning cycle. The transition toward renewable sources is changing the geography of dependency, not eliminating it. While fossil-fuel imports from any single region are declining, the materials required for batteries, solar panels, and grid components originate from a remarkably narrow set of suppliers. This concentration creates leverage that some of those suppliers have already demonstrated a willingness to use. Strategic stockpiles can dampen short-term shocks but do not address the medium-term vulnerability, which is the absence of alternative producers ready to scale within the relevant decision timelines. Diversification investments take years to mature, and progress so far has been concentrated in upstream extraction rather than the more capital-intensive midstream processing where the bottleneck actually sits. The recommendation is to weight near-term policy toward processing capacity, since cost premiums are recoverable but supply interruptions are not.", question: "What policy emphasis does the speaker recommend, and why?", options: ["Stockpiling, because it neutralises both short-term and medium-term supply vulnerabilities at once", "Upstream extraction, because that is where current diversification investment is already concentrated", "Fossil-fuel imports, because the renewable transition has created unmanageable new dependencies", "Midstream processing capacity, because the strategic chokepoint sits there"], answer: 3, ex: "本文の 'weight near-term policy toward processing capacity' / 'midstream processing where the bottleneck actually sits' を 'midstream processing capacity, because the strategic chokepoint sits there' とパラフレーズ。A は 'stockpiles... do not address the medium-term vulnerability' と矛盾、B は現状 ('so far has been concentrated') と将来推奨を取り違える、D は本文の論調と完全に逆。" },
    { topic: "Combined arms doctrine review", passage: "Doctrine review on combined arms integration. The lessons of recent observed conflicts are unsettling because they do not so much overturn established principles as expose how partially they have been implemented. The classical combination of fires, manoeuvre and protection still holds, but each element now depends on enabling functions — electronic warfare, persistent intelligence, casualty evacuation under threat — that earlier doctrine treated as supporting and that current observation suggests are decisive. Where one of these enablers fails, the others rapidly become unusable; where they succeed in combination, otherwise modest force ratios produce disproportionate effects. The implication is not a wholesale rewrite of doctrine but a recalibration of what counts as a core component versus a support function. Units that view enablers as optional augmentations rather than integral elements will continue to be surprised by an environment in which they are, in practice, the decisive variable.", question: "What revision to existing doctrine does the speaker propose?", options: ["The category boundary between core elements and enabling functions needs recalibrating", "Established combined-arms principles should be discarded as no longer applicable to current contexts", "Fires, manoeuvre and protection should be reorganised under a single unified command structure", "Enabling functions should be treated as fully optional augmentations to combined-arms units"], answer: 0, ex: "本文の 'a recalibration of what counts as a core component versus a support function' を 'the category boundary between core elements and enabling functions needs recalibrating' とパラフレーズ。A は本文 'principles still hold' と矛盾、B は本文に該当記述なし、C は本文の 'optional augmentations' を肯定提案として歪曲 (本文は否定的紹介)。L3 では 'recalibration' / 'core vs support' の抽象的調整論の理解が試される。" }
  ],
  4: [
    { topic: "Information warfare — strategic communications", passage: "The information environment has become a decisive domain of competition that precedes, accompanies, and outlasts kinetic operations. Adversaries exploit information asymmetries to undermine alliance cohesion, erode public support for military engagement, and create strategic paralysis in decision-making processes. Effective strategic communications requires not merely rapid response to disinformation, but the proactive shaping of the narrative space through credible, consistent, and coordinated messaging. The challenge, however, is that the alliance's commitment to democratic values and transparency imposes constraints on information operations that adversaries operating under authoritarian frameworks do not face. This asymmetry is fundamental and not amenable to technical solutions alone.", question: "What constraint does the speaker identify as limiting alliance information operations?", options: ["The high cost of modern communications technology", "The difficulty of coordinating messages across member nations", "The speed at which disinformation spreads online", "Commitment to democratic values and transparency"], answer: 3, ex: "The alliance's commitment to democratic values and transparency imposes constraints that adversaries under authoritarian frameworks do not face. Level 4 tests understanding of nuanced tension between strategic goals and foundational values." },
    { topic: "Multi-domain operations doctrine lecture", passage: "Multi-domain operations represent a paradigmatic shift in how we conceptualise and execute military campaigns. Rather than treating air, land, sea, space, and cyber as parallel but largely independent domains, the multi-domain framework seeks to exploit convergence — the simultaneous application of effects across domains to create dilemmas for the adversary that cannot be resolved by acting in any single domain. Air power, by virtue of its speed, reach, and flexibility, remains the principal enabler of cross-domain synergy. However, realising this potential demands a level of inter-service integration and digital interoperability that most allied nations are still developing. The transition is not merely technical but conceptual.", question: "What does the concept of convergence in multi-domain operations mean?", options: ["Simultaneously applying effects across domains to create irresolvable dilemmas", "Merging all military services into a single unified force", "Concentrating forces in one geographic area", "Using air power as the sole means of military action"], answer: 0, ex: "Convergence is defined as the simultaneous application of effects across domains creating dilemmas that cannot be resolved by acting in any single domain. Level 4 requires correctly applying specialist terminology defined within the audio." },
    { topic: "Strategic stability seminar", passage: "Strategic stability between nuclear-armed great powers has historically rested upon a combination of mutual vulnerability, transparency mechanisms, and arms control agreements that constrain destabilising capabilities. The progressive erosion of this architecture has raised profound concerns about the increased risk of miscalculation during crises. Emerging technologies, including hypersonic weapons, autonomous systems, and counterspace capabilities, complicate traditional concepts of strategic stability by compressing decision timelines and blurring distinctions between conventional and nuclear capabilities. Restoring elements of the previous architecture appears unlikely in the near term given current geopolitical tensions. Nevertheless, the underlying logic that motivated previous agreements retains its essential validity.", question: "What does the speaker say about the underlying logic of arms control?", options: ["It has been completely discredited", "It retains its essential validity", "It applies only to nuclear weapons", "It requires complete trust between adversaries"], answer: 1, ex: "The underlying logic that motivated previous agreements retains its essential validity. Level 4 tests recognition of enduring principles despite changing circumstances." },
    { topic: "Hybrid threat analysis seminar", passage: "Contemporary hybrid threats exploit the seams of traditional security frameworks. Adversaries deliberately operate below the threshold of armed conflict, employing combinations of cyber operations, disinformation, economic coercion, and proxy forces to achieve strategic objectives without triggering decisive collective response. The challenge for defending alliances is fundamental. Response thresholds calibrated to deter conventional aggression may prove ineffective against more ambiguous threats. Yet lowering response thresholds risks unintended escalation in genuinely contested situations. Resolving this tension requires both improved attribution capabilities and political will to act on the basis of accumulated evidence rather than indisputable proof. Neither capability nor will is currently sufficient.", question: "What does the speaker say is currently insufficient?", options: ["Military spending", "International cooperation", "Both attribution capabilities and political will", "Cyber defence technology"], answer: 2, ex: "Both attribution capabilities and political will are currently insufficient — the speaker explicitly identifies neither as sufficient. Level 4 tests careful tracking of complex assertions." },
    { topic: "Deterrence theory lecture", passage: "Contemporary deterrence theory has evolved considerably from its Cold War origins, when nuclear-centric models predominated. The current strategic environment requires conceptual frameworks capable of addressing simultaneous challenges from peer competitors, regional powers, and non-state actors operating across the full spectrum of conflict. Tailored deterrence approaches recognise that what deters a nuclear-armed great power may be entirely irrelevant against a transnational terrorist organisation, and that what credibly threatens an authoritarian regime may not affect a democratic adversary's calculations. This proliferation of deterrence relationships imposes substantial demands on intelligence, capabilities, and policymaking capacity. The integrated deterrence concept seeks to consolidate these multiple requirements within a unified framework.", question: "What characterises tailored deterrence approaches?", options: ["Application of identical measures to all adversaries", "Sole reliance on nuclear deterrence", "Withdrawal from deterrence relationships", "Recognition that different adversaries require different approaches"], answer: 3, ex: "Tailored deterrence recognises that what deters one adversary may be entirely irrelevant against another. Level 4 tests recognition of differentiated strategic principles." },
    { topic: "Emerging technology assessment", passage: "Emerging and disruptive technologies present complex strategic challenges that defy easy resolution. Artificial intelligence, quantum computing, biotechnology, and autonomous systems will reshape military capabilities in ways that remain incompletely understood. The pace of technological development outstrips traditional acquisition and integration processes, creating pressure for institutional adaptation. Adversaries face similar challenges but may operate under fewer constraints in pursuing rapid integration. The competitive dynamic risks decisions driven more by anxiety about lagging behind than by careful assessment of operational utility. Maintaining technological advantage requires not merely investment but disciplined judgement about which capabilities genuinely enhance operational effectiveness rather than merely reflecting fashion within technology communities.", question: "What does the speaker warn against?", options: ["Decisions driven by anxiety about lagging rather than careful assessment", "Investing in any new technology", "International cooperation in technology development", "Maintaining technological advantages"], answer: 0, ex: "The speaker warns against decisions driven by anxiety about lagging behind rather than careful assessment of operational utility. Level 4 tests recognition of subtle warnings within otherwise positive frames." },
    { topic: "Resilience strategic concept", passage: "Resilience has emerged as a central concept in contemporary security thinking, reflecting recognition that prevention of all hostile actions is impossible and that the capacity to absorb, adapt to, and recover from hostile actions is therefore essential. Alliance doctrine identifies seven baseline resilience requirements covering critical infrastructure, civilian capabilities, and continuity of government. Implementation depends primarily upon national authorities, although coordination through alliance mechanisms enhances coherence and identifies gaps. Resilience requirements interact with traditional military capabilities in complex ways. Investments in resilience may reduce vulnerabilities that adversaries seek to exploit, thereby contributing to deterrence by denial. Conversely, evident gaps in resilience may incentivise hostile action by suggesting attractive targets.", question: "How does the speaker describe the relationship between resilience and deterrence?", options: ["Resilience and deterrence are unrelated concepts", "Resilience investments may contribute to deterrence by denial", "Resilience eliminates the need for deterrence", "Deterrence makes resilience unnecessary"], answer: 1, ex: "Investments in resilience may reduce vulnerabilities adversaries seek to exploit, contributing to deterrence by denial. Level 4 tests understanding of complex conceptual relationships." },
    { topic: "Burden sharing analysis seminar", passage: "Burden sharing within the alliance has been a perennial source of contention since NATO's establishment, but the debate has acquired new intensity in the contemporary period. The benchmark of two percent of gross domestic product, agreed at the Wales Summit, has become a politically charged metric despite its acknowledged limitations as a measure of meaningful contribution. Defence spending alone captures neither the quality of capabilities developed nor the operational contributions made by member states. A nation might exceed the spending threshold while investing inefficiently in capabilities of marginal alliance utility, while another nation might fall below the threshold yet provide highly capable forces in critical operations. More sophisticated assessments incorporate measures of capability development, operational deployment, and acceptance of risk in alliance missions.", question: "What limitation of the spending metric does the speaker identify?", options: ["It is too difficult to calculate", "It is rejected by most member states", "It captures neither quality of capabilities nor operational contributions", "It encourages excessive defence spending"], answer: 2, ex: "Defence spending alone captures neither the quality of capabilities developed nor the operational contributions made. Level 4 tests understanding of analytical critique." },
    { topic: "Civil-military relations lecture", passage: "Civil-military relations in democratic societies require continuous attention to maintain appropriate balance. Military expertise must inform decisions on use of force without supplanting civilian authority over fundamental questions of war and peace. Civilian leaders must engage substantively with military advice without micromanaging operational details. The boundary between strategic direction and operational interference is not always clear, and reasonable people disagree about specific cases. Political polarisation in some allied nations has placed additional strain on these relationships, as military leaders navigate environments where their professional advice may be politicised by partisan interests. Maintaining the apolitical character of military service is essential but increasingly challenging.", question: "What does the speaker say about civilian-military boundaries?", options: ["They are completely clear in all cases", "Civilian leaders should never engage with military advice", "Military leaders should always defer to politicians", "The boundary between strategic direction and operational interference is not always clear"], answer: 3, ex: "The boundary between strategic direction and operational interference is not always clear, and reasonable people disagree about specific cases. Level 4 recognition of analytical nuance." },
    { topic: "Nuclear posture debate", passage: "The debate over alliance nuclear posture has intensified following recent developments. Some advocate enhancements to current arrangements, including modernisation of dual-capable aircraft and consideration of expanded sharing arrangements with additional allies. Others argue that any expansion would prove escalatory and counterproductive, undermining strategic stability without enhancing deterrence. The middle position emphasises maintaining current arrangements while ensuring their continued credibility through investment in supporting capabilities. Resolution of this debate requires addressing not only military requirements but also political sustainability among diverse member states with varying historical perspectives on nuclear weapons. The debate is unlikely to reach definitive resolution.", question: "What does the middle position emphasise?", options: ["Maintaining current arrangements while ensuring their credibility", "Significant expansion of nuclear arrangements", "Complete elimination of nuclear weapons", "Withdrawal from nuclear sharing entirely"], answer: 0, ex: "The middle position emphasises maintaining current arrangements while ensuring continued credibility through investment in supporting capabilities. Level 4 distinguishes between three positions within a complex debate." },
    { topic: "Space situational awareness briefing", passage: "Good morning. The space situational awareness briefing focuses on the increasingly congested orbital environment. Catalogued objects in low Earth orbit have grown by approximately forty percent over the past five years, while uncatalogued debris likely exceeds tracked populations by an order of magnitude. The implications extend well beyond collision risk. Adversary counterspace capabilities increasingly exploit ambiguity between intentional interference and routine orbital activity, complicating attribution and proportionate response. Defensive measures including manoeuvre, redundancy, and disaggregation impose substantial cost penalties on space-based capabilities. The fundamental challenge is that purely technical responses cannot resolve what is essentially a problem of strategic restraint, since unilateral defensive measures provoke reciprocal investments in offensive capabilities, generating instability the technical community alone cannot reverse. Norms-based approaches require political investments that have proved difficult to sustain, yet remain indispensable to long-term stability.", question: "What does the briefer identify as a fundamental challenge that purely technical responses cannot resolve?", options: ["Insufficient sensor coverage of low Earth orbit", "The need for strategic restraint that technical measures alone cannot create", "Outdated cataloguing of orbital debris", "Lack of redundancy in defensive measures"], answer: 1, ex: "「purely technical responses cannot resolve what is essentially a problem of strategic restraint」— option B はこの主張を直接反映。A は技術的問題、C は手続き的問題、D は防御策の不足として誤誘導するが、いずれも passage が「技術以外」の核心と区別している。Level 4 は「技術 vs 戦略」の分離を聴き取る力を試す。" },
    { topic: "Disinformation resilience workshop", passage: "Today's workshop addresses the construction of societal resilience against sustained disinformation campaigns. The temptation to focus exclusively on detection and removal of false content addresses symptoms rather than underlying vulnerabilities. Empirical evidence suggests that resilience emerges from media literacy, institutional trust, and habits of evidence evaluation that take years to cultivate but degrade quickly under sustained pressure. Defensive measures concentrated on platform-level interventions face inherent limitations, since adversaries adapt rapidly and free expression principles constrain available responses in democratic societies. The more durable approach invests in citizen capabilities and trustworthy institutions, recognising that resilience is fundamentally a societal property rather than a technical achievement. Yet this longer-term orientation conflicts with political incentives for visible immediate action, generating policy preferences for measures whose visibility exceeds their effectiveness. Bridging this gap between political demand and analytical guidance constitutes one of the principal challenges in this domain.", question: "What does the speaker say about platform-level interventions?", options: ["They represent the most durable solution to disinformation", "They have completely resolved the disinformation problem", "They face inherent limitations due to adversary adaptation and free expression constraints", "They should be abandoned entirely"], answer: 2, ex: "「Defensive measures concentrated on platform-level interventions face inherent limitations, since adversaries adapt rapidly and free expression principles constrain available responses」— option C はこの記述を直接反映。A は「最も持続的」として正反対 (passage は社会的能力を最も持続的とする)、C は楽観的誤認、D は極端な拒絶として正反対。Level 4 は「限界がある」と「無効である」の区別を聴き取る力を試す。" },
    { topic: "Counter-intelligence threat assessment", passage: "The contemporary counter-intelligence threat assessment indicates a substantial shift in adversary approaches. Traditional human intelligence operations, while continuing, have been supplemented by aggressive cyber-enabled collection and exploitation of insider vulnerabilities through digital social engineering. The volume of adversary activity has increased substantially, but more concerning is the growing sophistication in identifying personnel with access to sensitive information through analysis of publicly available data, including social media patterns and professional networking platforms. Defensive responses concentrated on perimeter security and clearance procedures address only part of the contemporary threat surface. Personnel awareness, behavioural anomaly detection, and reduction of unnecessary information exposure all merit greater investment than they currently receive. The cultural challenge is substantial, since these measures intrude upon expectations of personal privacy that personnel reasonably value, requiring careful calibration to maintain both security and morale.", question: "What does the assessment identify as requiring careful calibration?", options: ["The volume of adversary intelligence operations", "Perimeter security and clearance procedures", "The number of personnel with security clearances", "Defensive measures that intrude on personal privacy expectations"], answer: 3, ex: "「these measures intrude upon expectations of personal privacy that personnel reasonably value, requiring careful calibration」— option D はこの記述を直接反映。A は脅威側、B は既存対策の不十分性として誤誘導、D はクリアランス保有者数として的外れ。Level 4 は「セキュリティ vs プライバシー」のトレードオフを聴き取る力を試す。" },
    { topic: "Energy transition strategic dependencies", passage: "The energy transition introduces strategic dependencies whose implications remain incompletely appreciated in defence planning. Renewable energy deployment reduces dependence on fossil fuel supply chains but increases reliance upon critical minerals, advanced battery technologies, and the manufacturing capacities concentrated in specific geographic regions. The replacement of one set of dependencies with another does not constitute genuine independence, though it does change the nature of vulnerabilities and the actors capable of exploiting them. Operational implications include changes in fuel supply tempo, the energy intensity of advanced platforms, and the resilience of distributed generation versus centralised generation in contested environments. Defence planning that treats the energy transition primarily as an environmental matter, separable from operational and strategic considerations, misunderstands the depth of the changes underway. Integration of energy transition planning with broader strategic analysis remains insufficient across most allied defence establishments.", question: "What does the briefer say about defence planning that treats the energy transition primarily as environmental?", options: ["It misunderstands the depth of the changes underway", "It correctly separates environmental and strategic considerations", "It has been adopted by most allied defence establishments", "It eliminates strategic dependencies entirely"], answer: 0, ex: "「Defence planning that treats the energy transition primarily as an environmental matter, separable from operational and strategic considerations, misunderstands the depth of the changes underway」— option A はこの直接反映。A は「正しく分離」として正反対、C は事実誤認 (briefer は不十分性を指摘)、D は依存性の解消として誇張。Level 4 では「環境問題」と「戦略問題」の不可分性を聴き取る力が問われる。" },
    { topic: "Arctic security architecture analysis", passage: "The Arctic security architecture is undergoing rapid evolution driven by environmental, economic, and geopolitical changes whose interactions resist clean analytical separation. Receding ice cover opens previously inaccessible sea routes and resource access, generating commercial and strategic interest from both Arctic and non-Arctic states. Existing governance frameworks, particularly the Arctic Council, were designed for a more cooperative environment and prove ill-suited to managing genuine strategic competition while maintaining the practical cooperation that environmental and humanitarian challenges require. The accession of Finland and Sweden to the alliance fundamentally alters the regional balance, with implications still being absorbed by all parties. Russian responses to this shift include both military reinforcement and renewed diplomatic engagement with non-Arctic powers, particularly China, whose Arctic interests remain strategically significant despite geographic distance. Coherent Western approaches require reconciliation of national interests that diverge in important respects, a challenge that the rhetoric of alliance solidarity should not obscure.", question: "What does the analyst say about reconciliation of Western national interests in the Arctic?", options: ["National interests are essentially identical and require no reconciliation", "National interests diverge in important respects despite alliance solidarity rhetoric", "Alliance solidarity has fully resolved divergences in national interests", "Reconciliation is impossible and should not be attempted"], answer: 1, ex: "「Coherent Western approaches require reconciliation of national interests that diverge in important respects, a challenge that the rhetoric of alliance solidarity should not obscure」— option B はこの主張を直接反映。A は「同一」として正反対、B は「解決済み」として誇張的誤認、D は「不可能」として極端な誤認。Level 4 では「公式 rhetoric (連帯)」と「実際の差異 (国益乖離)」のギャップを聴き取る分析力が問われる。" }
  ],
};
